export default {"intro":{"ageQ":"Сколько лет ребёнку?","ages":["3-5","6-8","9-12"],"genderQ":"Это мальчик или девочка?","genders":["Мальчик","Девочка"]},"questions":[{"id":"q1","text":"Чем ребёнок занимается, когда никто не предлагает занятий?","options":[{"scale":"builder","text":"Что-то строит или собирает"},{"scale":"storyteller","text":"Придумывает истории, говорит за игрушки"},{"scale":"mover","text":"Бегает, лазает, прыгает"},{"scale":"artist","text":"Рисует, лепит, вырезает"},{"scale":"inventor","text":"Разбирает вещи или ставит опыты: что будет, если…"},{"scale":"explorer","text":"Рассматривает, наблюдает, что-то ищет и находит"},{"scale":"leader","text":"Зовёт других и придумывает общую игру"},{"scale":"helper","text":"Идёт помогать вам или заботится о ком-то"}]},{"id":"q2","text":"Какие игрушки занимают ребёнка дольше всего?","options":[{"scale":"inventor","text":"Головоломки, наборы для опытов"},{"scale":"helper","text":"Куклы, зверушки, игры в «дочки-матери» и доктора"},{"scale":"leader","text":"Игры с правилами, в которые играют с другими"},{"scale":"explorer","text":"Находки с улицы: камни, жуки, палки"},{"scale":"builder","text":"Конструкторы и кубики"},{"scale":"storyteller","text":"Книги, фигурки и игрушки для историй"},{"scale":"artist","text":"Краски, пластилин, наборы для творчества"},{"scale":"mover","text":"Мяч, самокат, скакалка: всё для движения"}]},{"id":"q3","text":"О чём ребёнок чаще всего спрашивает «почему»?","options":[{"scale":"inventor","text":"Как устроены вещи и механизмы"},{"scale":"explorer","text":"Про животных, природу, космос"},{"scale":"storyteller","text":"Что значат слова, чем кончилась история"},{"scale":"helper","text":"Почему люди грустят, злятся, радуются"}]},{"id":"q4","text":"Что ребёнок выбирает на экране, когда выбор свободный?","options":[{"scale":"builder","text":"Игры, где строят миры и города"},{"scale":"artist","text":"Рисование, музыку, как что-то мастерят"},{"scale":"mover","text":"Спорт, танцы, трюки"},{"scale":"leader","text":"Соревнования и челленджи"}]},{"id":"q5","text":"Что ребёнок делает на детской площадке?","options":[{"scale":"mover","text":"Сразу лезет на самое высокое"},{"scale":"leader","text":"Собирает детей и придумывает игру"},{"scale":"explorer","text":"Обходит все углы, что-то находит"},{"scale":"helper","text":"Опекает младших, делится"}]},{"id":"q6","text":"Какие книги и истории любит ребёнок?","options":[{"scale":"storyteller","text":"Сказки и приключения с героями"},{"scale":"inventor","text":"Энциклопедии и «как это работает»"},{"scale":"artist","text":"Где красивые картинки, любит их разглядывать"},{"scale":"builder","text":"Про машины, технику, стройку"}]},{"id":"q7","text":"Какой подарок ребёнок выберет для себя?","options":[{"scale":"builder","text":"Конструктор"},{"scale":"artist","text":"Набор для творчества или инструмент"},{"scale":"inventor","text":"Набор юного учёного"},{"scale":"mover","text":"Мяч, самокат, велосипед"}]},{"id":"q8","text":"Чем ребёнок гордится больше всего?","options":[{"scale":"leader","text":"Победа или главная роль"},{"scale":"helper","text":"Помощь кому-то"},{"scale":"storyteller","text":"Выступление, рассказ, удачная шутка"},{"scale":"explorer","text":"Находка или новое знание"}]},{"id":"q9","text":"Сломалась любимая игрушка. Что сделает ребёнок?","options":[{"scale":"builder","text":"Пытается починить"},{"scale":"inventor","text":"Разбирает, чтобы посмотреть, что внутри"},{"scale":"artist","text":"Превращает во что-то другое"},{"scale":"storyteller","text":"Придумывает историю, что с ней случилось"}]},{"id":"q10","text":"Новая компания детей. Как ведёт себя ребёнок?","options":[{"scale":"leader","text":"Предлагает, во что играть"},{"scale":"helper","text":"Находит одного ребёнка и дружит с ним"},{"scale":"explorer","text":"Сначала наблюдает и осматривается"},{"scale":"mover","text":"Сразу включается в беготню"}]},{"id":"q11","text":"Задача не получается. Что делает ребёнок?","options":[{"scale":"inventor","text":"Пробует другой способ"},{"scale":"builder","text":"Делает шаг за шагом, пока не получится"},{"scale":"leader","text":"Зовёт других делать вместе"},{"scale":"storyteller","text":"Рассуждает вслух, обсуждает"}]},{"id":"q12","text":"Проигрыш в игре. Что дальше?","options":[{"scale":"mover","text":"Требует реванш прямо сейчас"},{"scale":"leader","text":"Спорит о правилах, договаривается"},{"scale":"helper","text":"Поздравляет, переживает за других"},{"scale":"artist","text":"Уходит заниматься своим делом"}]},{"id":"q13","text":"Свободный день. Что выберет ребёнок?","options":[{"scale":"explorer","text":"Лес, зоопарк, музей"},{"scale":"mover","text":"Бассейн, батуты, спорт"},{"scale":"artist","text":"Мастерить, рисовать, музыку"},{"scale":"storyteller","text":"Театр, кино, книги"}]},{"id":"q14","text":"Рядом кто-то плачет. Что делает ребёнок?","options":[{"scale":"helper","text":"Подходит утешить"},{"scale":"leader","text":"Зовёт взрослого, берёт дело в свои руки"},{"scale":"storyteller","text":"Расспрашивает, что случилось"},{"scale":"inventor","text":"Пытается устранить причину"}]},{"id":"q15","text":"Собираетесь в поездку. Как собирается ребёнок?","options":[{"scale":"builder","text":"Складывает вещи по порядку"},{"scale":"explorer","text":"Расспрашивает, куда едем и что там есть"},{"scale":"artist","text":"Выбирает наряд и любимые мелочи"},{"scale":"mover","text":"Не может усидеть, уже у двери"}]},{"id":"q16","text":"Ребёнку дали коробку с разными деталями. Что будет дальше?","options":[{"scale":"builder","text":"Сразу что-то строит"},{"scale":"inventor","text":"Сортирует и проверяет, что для чего"},{"scale":"helper","text":"Придумывает, кому из этого сделать подарок"},{"scale":"explorer","text":"Рассматривает каждую и спрашивает, откуда она"}]}],"sliders":{"labels":["Редко","Иногда","Часто","Почти всегда","Всегда"],"items":[{"id":"energy","text":"У ребёнка много энергии, трудно усидеть на месте"},{"id":"boldness","text":"Смело идёт в новое: место, люди, занятие"},{"id":"persistence","text":"Доводит начатое до конца, даже когда трудно"},{"id":"sensitivity","text":"Тонко чувствует настроение других и остро переживает"},{"id":"sociability","text":"Легко заводит знакомства и любит быть среди людей"},{"id":"pace","text":"Любит, когда всё быстро, и не любит ждать"}]},"goal":{"text":"Что вам важнее всего узнать?","options":[{"id":"activity","text":"Какой кружок или секцию выбрать"},{"id":"strengths","text":"В чём ребёнок сильнее всего"},{"id":"future","text":"Что попробовать с ребёнком дальше"},{"id":"character","text":"Как найти подход к ребёнку"}]},"types":{"builder":{"name":"Строитель","nameF":"Строитель","tagline":"Думает руками и видит, как собрать целое из частей","careers":"инженер, архитектор, механик, столяр"},"inventor":{"name":"Изобретатель","nameF":"Изобретатель","tagline":"Хочет знать, как всё устроено, и пробует по-своему","careers":"учёный, программист, аналитик, врач-исследователь"},"storyteller":{"name":"Рассказчик","nameF":"Рассказчик","tagline":"Мыслит словами и историями, легко увлекает других","careers":"журналист, писатель, юрист, актёр"},"artist":{"name":"Художник","nameF":"Художник","tagline":"Замечает красоту и детали, создаёт своё","careers":"дизайнер, иллюстратор, музыкант, архитектор"},"explorer":{"name":"Исследователь","nameF":"Исследователь","tagline":"Наблюдает, собирает факты и идёт смотреть, что за углом","careers":"биолог, ветеринар, географ, эколог"},"leader":{"name":"Лидер","nameF":"Лидер","tagline":"Берёт инициативу, договаривается и ведёт за собой","careers":"предприниматель, менеджер, организатор, тренер"},"helper":{"name":"Помощник","nameF":"Помощник","tagline":"Чувствует других и раньше всех приходит на помощь","careers":"врач, учитель, психолог, ветеринар"},"mover":{"name":"Непоседа","nameF":"Непоседа","tagline":"Думает в движении: сначала попробует телом, потом объяснит","careers":"спортсмен, тренер, хореограф, спасатель"}},"shade":{"swift":{"m":"быстрый","f":"быстрый"},"calm":{"m":"вдумчивый","f":"вдумчивый"}},"disclaimer":"Основано на наблюдениях родителя. Это не психологическая и не медицинская оценка.","report":{"builder":{"about":"{name} думает руками. Понять вещь проще всего, если собрать, разобрать или построить её своими руками. Здесь сразу видно, как из частей получается целое, и покоя нет, пока конструкция не встанет ровно.","hooks":"Увлекает: задачи с понятным результатом, который можно потрогать. Быстро надоедает: долгие объяснения без дела и занятия, где «нечего строить».","strengths":["Пространственное мышление: представляет, как детали сойдутся","Терпение в работе шаг за шагом","Доводит до работающего результата"],"grow":"Объяснять словами свои действия: что и зачем. Просите рассказать о постройке, как экскурсовода.","say":["«Расскажи, как тебе пришла эта идея»","«Что было самым трудным в этой постройке?»","«Что ты изменишь в следующий раз?»"],"ages":{"3-5":"крупный конструктор, песок и вода, постройки из коробок","6-8":"конструкторы с инструкцией, оригами, простые модели, робототехника для начинающих","9-12":"моделирование, 3D-ручка или 3D-редактор, столярная или техническая мастерская"},"plan":["Неделя 1. Постройка по образцу: одна модель по инструкции от начала до конца.","Неделя 2. Своя версия: изменить модель так, чтобы она стала лучше.","Неделя 3. Задача с ограничением: мост из бумаги, который выдержит книгу.","Неделя 4. Проект для семьи: сделать полезную вещь для дома и показать её."]},"inventor":{"about":"{name} хочет знать, как всё устроено, и проверяет это на деле. Готовый ответ здесь менее интересен, чем собственный опыт: попробовать, ошибиться и попробовать иначе.","hooks":"Увлекает: загадки, опыты, вопрос «а что будет, если…». Быстро надоедает: повторять одно и то же и делать «потому что так надо».","strengths":["Любопытство и умение задавать точные вопросы","Логика: видит причину и следствие","Не боится ошибок, ищет другой способ"],"grow":"Заканчивать начатое. Идей пока больше, чем доведённых дел. Договаривайтесь об одном маленьком финише.","say":["«Как ты это проверишь?»","«Отличный вопрос, давай узнаем вместе»","«Ошибка тоже результат. Что она показала?»"],"ages":{"3-5":"игры с водой, воронки и стаканчики, сортировка, простые головоломки","6-8":"наборы юного учёного, шахматы, логические игры, первые шаги в программировании","9-12":"программирование, электроника, научный кружок, олимпиадные задачи"},"plan":["Неделя 1. Один опыт в день на 10 минут: что тонет, что катится, что растворяется.","Неделя 2. Дневник «казалось, а оказалось»: предположение до опыта и результат после.","Неделя 3. Логика: одна игра или головоломка, сложность растёт каждый день.","Неделя 4. Свой эксперимент: придумать вопрос, проверить и показать семье."]},"storyteller":{"about":"{name} мыслит словами и историями. Лучше всего запоминается то, что рассказано как сюжет, а обычный день легко превращается в рассказ. И очень важно, чтобы этот рассказ слушали.","hooks":"Увлекает: книги, разговоры, роли, выступления. Быстро надоедает: молчаливая работа в одиночку и задания без истории и героя.","strengths":["Богатая речь и память на истории","Воображение: придумывает миры и персонажей","Умеет увлечь и убедить"],"grow":"Слушать других так же охотно, как говорить. Играйте в «интервью», где вопросы задаёт ребёнок.","say":["«Расскажи, что было дальше»","«Какое точное слово, мне очень нравится»","«А что чувствовал герой?»"],"ages":{"3-5":"чтение вслух с вопросами, кукольный театр, сочинение сказок перед сном","6-8":"театральная студия, свой комикс или книжка, иностранный язык","9-12":"дебаты, школьная газета или блог, литературный или театральный кружок"},"plan":["Неделя 1. История дня: каждый вечер три предложения о главном событии.","Неделя 2. Своя книжка: 6 страниц с рисунками и текстом.","Неделя 3. Интервью: расспросить бабушку, соседа или друга и пересказать.","Неделя 4. Выступление: показать историю семье, с ролями или куклами."]},"artist":{"about":"{name} замечает то, что другие пропускают: цвет, форму, звук, настроение. Думает образами и хочет делать по-своему, а не как в образце.","hooks":"Увлекает: свобода выбрать материал и результат. Быстро надоедает: раскраски «по номерам», спешка и оценка «правильно или неправильно».","strengths":["Наблюдательность и чувство деталей","Оригинальные идеи","Умеет надолго погрузиться в своё дело"],"grow":"Показывать работу другим и спокойно принимать замечания. Начните с вопроса «а что здесь нравится именно тебе?».","say":["«Расскажи, что здесь происходит»","«Я вижу, сколько труда вложено в эти детали»","«Как ты подбираешь цвета?»"],"ages":{"3-5":"краски и пальчиковое рисование, лепка, музыка и танцы под неё","6-8":"художественная студия, музыкальный инструмент, поделки из подручного","9-12":"рисунок или цифровая иллюстрация, фото и видео, музыкальная группа или хор"},"plan":["Неделя 1. Один материал в день: карандаш, краски, пластилин, бумага, природные материалы.","Неделя 2. Одна тема, пять способов: нарисовать, слепить, сфотографировать, склеить, сыграть.","Неделя 3. Большая работа: один проект на всю неделю, по 15 минут в день.","Неделя 4. Домашняя выставка: выбрать лучшие работы, подписать и пригласить семью."]},"explorer":{"about":"{name} сначала смотрит, потом действует. Собирает факты, замечает закономерности и помнит удивительные подробности о животных, планетах или динозаврах.","hooks":"Увлекает: всё новое, живое и настоящее, коллекции и карты. Быстро надоедает: сидеть в четырёх стенах и учить то, что нельзя увидеть.","strengths":["Наблюдательность","Память на факты и подробности","Самостоятельность: умеет занять себя"],"grow":"Входить в новую компанию. Сначала нужно время, чтобы осмотреться. Не торопите, дайте 10 минут понаблюдать.","say":["«Что нового удалось заметить сегодня?»","«Покажи свою находку»","«Давай проверим, так ли это»"],"ages":{"3-5":"прогулки с лупой, уход за растением, книги о животных","6-8":"кружок юных натуралистов, коллекции, скауты, походы","9-12":"биология или астрономия, ориентирование, волонтёрство в приюте для животных"},"plan":["Неделя 1. Прогулка-исследование: каждый день найти три новые вещи на знакомом маршруте.","Неделя 2. Коллекция: собрать, разложить и подписать 10 находок.","Неделя 3. Наблюдение: неделя с одним объектом (растение, птицы, погода) и запись каждый день.","Неделя 4. Экспедиция: спланировать семейную вылазку и вести всех по маршруту."]},"leader":{"about":"{name} быстро понимает, что нужно сделать, и собирает для этого людей. Предлагает правила, распределяет роли и переживает за общий результат.","hooks":"Увлекает: цель, команда и возможность решать. Быстро надоедает: задания без выбора и ситуации, где от ребёнка ничего не зависит.","strengths":["Инициатива: начинает раньше других","Умеет договариваться","Берёт ответственность за результат"],"grow":"Уступать и проигрывать. Давайте иногда роль «помощника капитана», где командует кто-то другой.","say":["«Как ты решаешь, кто что делает?»","«Что думают остальные? Спроси их»","«Сегодня за это отвечаешь только ты»"],"ages":{"3-5":"игры с правилами, «дежурный по дому», простые командные игры","6-8":"командный спорт, настольные стратегии, скауты","9-12":"капитан команды, школьное самоуправление, свой маленький проект или ярмарка"},"plan":["Неделя 1. Одно своё дело дома: полная ответственность на всю неделю.","Неделя 2. Семейная игра: объясняет правила и ведёт игру.","Неделя 3. Мини-проект: организовать прогулку или праздник для двух-трёх человек.","Неделя 4. Смена ролей: неделя, когда ребёнок помогает и следует чужому плану."]},"helper":{"about":"{name} считывает настроение людей раньше, чем они что-то скажут. Главное здесь отношения: помнить, кто что любит, и стараться, чтобы всем было хорошо.","hooks":"Увлекает: дела вместе с кем-то и для кого-то. Быстро надоедает: соперничество и занятия, где каждый сам за себя.","strengths":["Эмпатия: понимает чувства других","Надёжность и забота","Умеет мирить и объединять"],"grow":"Говорить «нет» и называть свои желания. Спрашивайте чаще «а чего хочешь ты?».","say":["«Ты замечаешь, когда кому-то грустно. Это ценно»","«А чего хочется тебе?»","«Можно отказаться, и дружба от этого не пострадает»"],"ages":{"3-5":"ролевые игры в доктора и семью, уход за питомцем или растением, помощь на кухне","6-8":"кружки в маленьких группах, уход за животными, первая помощь для детей","9-12":"волонтёрство, наставник для младших, психология или биология"},"plan":["Неделя 1. Одно доброе дело в день и короткий разговор вечером, как это было.","Неделя 2. Забота о живом: поливать растение или кормить питомца становится ежедневным делом ребёнка, вы проверяете.","Неделя 3. Мои желания: каждый день один выбор делает только ребёнок (ужин, игра, маршрут).","Неделя 4. Подарок своими руками: придумать и сделать для близкого человека."]},"mover":{"about":"{name} думает в движении. Понять и запомнить легче, когда участвует тело: показать, попробовать, повторить. Энергии здесь больше, чем требует обычный день.","hooks":"Увлекает: скорость, вызов, новые трюки. Быстро надоедает: долго сидеть и слушать без возможности встать.","strengths":["Координация и ловкость","Смелость пробовать новое","Упорство в тренировке навыка"],"grow":"Спокойным занятиям. Давайте подвигаться перед ними: 10 минут активности помогают потом усидеть.","say":["«Покажи, как ты это делаешь»","«Вижу, сколько было попыток, прежде чем получилось»","«Сначала побегай, потом сядем»"],"ages":{"3-5":"беговел, полоса препятствий дома, плавание, танцы","6-8":"гимнастика, плавание, командные игры, единоборства","9-12":"секция по выбранному виду спорта, скалодром, танцевальная команда"},"plan":["Неделя 1. 10 минут движения каждый день: одна новая игра или упражнение.","Неделя 2. Один навык: выбрать трюк (скакалка, стойка, мяч) и тренировать всю неделю.","Неделя 3. Проба: одно пробное занятие в новой секции.","Неделя 4. Показ: ребёнок показывает семье навык и выбирает следующий."]}},"cards":[{"id":"builder-1","scale":"builder","art":"📄🌉🧸","title":"Мост из бумаги","task":{"3-5":"Положите лист бумаги между двумя книгами. Сколько игрушек он выдержит? Сложите лист гармошкой и проверьте ещё раз.","6-8":"Постройте мост из одного листа бумаги между двумя книгами. Задача: чтобы он выдержал 10 монет. Скотч и ножницы нельзя.","9-12":"Три листа бумаги и скотч. Постройте мост длиной 30 см, который выдержит книгу. Сначала нарисуйте план, потом сравните с тем, что получилось."},"why":"Ребёнок на деле видит, что форма делает слабый материал прочным. Это основа инженерного мышления.","tip":"Не подсказывайте решение. Спросите: «Как думаешь, почему провисло? Что можно изменить?»","need":{"3-5":"лист бумаги, две книги, 5–6 лёгких игрушек","6-8":"лист бумаги, две книги, 10 монет или ластиков","9-12":"три листа бумаги, скотч, линейка, книга"},"steps":{"3-5":["Положите книги рядом, на расстоянии ладони взрослого, и накройте лист сверху как мост.","Ставьте игрушки на мост по одной и считайте вслух, сколько выдержит.","Сложите лист гармошкой вместе с ребёнком и положите снова.","Проверьте ещё раз и сравните: сколько игрушек было и сколько стало."],"6-8":["Задача: мост из одного листа должен выдержать 10 монет. Скотч и ножницы нельзя.","Первая попытка: ребёнок кладёт лист как есть и проверяет.","Дайте 3 минуты на поиски: можно гнуть, складывать, сворачивать.","Проверьте лучший вариант и попросите объяснить, почему он держит."],"9-12":["Условие: мост длиной 30 см должен выдержать книгу.","Сначала ребёнок рисует план: какая форма, где опоры.","Сборка по плану, 5 минут.","Испытание книгой. Сравните план и результат: что пришлось менять и почему."]}},{"id":"builder-2","scale":"builder","art":"🧱🗼📏","title":"Самая высокая башня","task":{"3-5":"Постройте башню из кубиков или пластиковых стаканов выше, чем колено ребёнка. Потом выше пояса.","6-8":"У вас 20 предметов из кухни (стаканчики, губки, коробки). Постройте башню выше стола. Упала? Найдите, какой этаж подвёл.","9-12":"Башня только из бумаги и скотча, без опоры на стену. Цель: 1 метр. Замерьте, запишите рекорд, попробуйте побить."},"why":"Башня учит равновесию, терпению и поиску ошибки: упало не «всё», а подвёл один этаж.","tip":"Когда башня падает, не утешайте сразу. Спросите: «Какой этаж подвёл?»","need":{"3-5":"кубики или пластиковые стаканы","6-8":"20 предметов из кухни: стаканчики, губки, коробки","9-12":"бумага, скотч, рулетка"},"steps":{"3-5":["Постройте вместе башню выше колена ребёнка.","Теперь цель выше: до пояса. Строит ребёнок, вы подаёте.","Если упала, посмотрите вместе, где она качнулась.","Постройте ещё раз с широким низом и сравните."],"6-8":["Разложите предметы и дайте минуту их рассмотреть.","Задача: башня выше стола. Строит ребёнок.","Упала? Найдите этаж, который подвёл, и замените его.","Измерьте готовую башню ладонями и запомните рекорд."],"9-12":["Условие: башня только из бумаги и скотча, без опоры на стену. Цель: 1 метр.","Ребёнок выбирает форму опор: трубки, треугольники или гармошка.","Сборка 7 минут, потом замер.","Запишите рекорд и одну идею, как его побить в следующий раз."]}},{"id":"builder-3","scale":"builder","art":"📦🏠🧸","title":"Домик для игрушки","task":{"3-5":"Сделайте из коробки и подушек домик для любимой игрушки. Где дверь? Где кровать?","6-8":"Постройте из коробки дом для игрушки: дверь, которая открывается, и окно. Ножницами работает взрослый.","9-12":"Спроектируйте дом из коробки: сначала чертёж с размерами, потом сборка. В доме должно быть два этажа и лестница."},"why":"Ребёнок планирует пространство: что где стоит и зачем. Так появляется привычка сначала думать, потом строить.","tip":"Задавайте вопросы от имени игрушки: «А где я буду спать? Как я войду?»","need":{"3-5":"коробка, подушки, любимая игрушка","6-8":"коробка, фломастеры, скотч, ножницы (режет взрослый)","9-12":"коробка, линейка, бумага, скотч, ножницы"},"steps":{"3-5":["Спросите: какой дом нужен игрушке? Большой или маленький?","Постройте стены из подушек и коробки.","Найдите вместе, где дверь и где кровать.","Заселите игрушку и пожелайте ей спокойной ночи."],"6-8":["Ребёнок отмечает фломастером, где будут дверь и окно.","Взрослый вырезает по линиям, дверь оставляет на одной стороне, чтобы открывалась.","Ребёнок оформляет дом: стены, коврик, мебель из мелких коробочек.","Экскурсия по дому: ребёнок показывает и рассказывает."],"9-12":["Сначала чертёж: два этажа и лестница, размеры в сантиметрах.","Ребёнок размечает детали по линейке.","Сборка. Острые и тугие места режет взрослый.","Сверьте дом с чертежом: что совпало, что пришлось изменить."]}},{"id":"builder-4","scale":"builder","art":"🛝⚽🚗","title":"Горка для шарика","task":{"3-5":"Сделайте горку из картона или книги. Катайте мячик. Что едет быстрее: мячик или машинка?","6-8":"Соберите трассу для шарика из картонных трубок и скотча на стене или двери. Шарик должен ехать не меньше 5 секунд.","9-12":"Трасса для шарика с тремя поворотами и финишем в стакане. Засеките время. Задача: сделать спуск медленнее, не останавливая шарик."},"why":"Опыт с наклоном и скоростью: ребёнок самостоятельно меняет условие и сразу видит результат.","tip":"Перед каждым запуском просите прогноз: «Как думаешь, что будет быстрее?»","need":{"3-5":"картонка или большая книга, мяч крупнее кулака ребёнка, машинка","6-8":"картонные трубки от рулонов, бумажный скотч, мячик или шарик из фольги","9-12":"трубки, картон, скотч, стакан, секундомер"},"steps":{"3-5":["Сделайте горку: один край картонки положите на диван или стопку книг.","Скатите мячик, потом машинку. Что приехало быстрее?","Поднимите край выше и проверьте ещё раз.","Третий предмет для спуска пусть выберет ребёнок."],"6-8":["Приклейте первую трубку к двери или стене под наклоном.","Ребёнок добавляет следующие, чтобы шарик переходил из одной в другую.","Запускайте после каждой новой детали и поправляйте.","Цель: шарик едет не меньше 5 секунд. Считайте вслух."],"9-12":["Условие: три поворота и финиш в стакане.","Ребёнок собирает трассу и делает пробный запуск.","Замер времени. Новая задача: сделать спуск медленнее, но чтобы шарик не останавливался.","Запишите время до и после и что именно изменили."]}},{"id":"builder-5","scale":"builder","art":"🔧🪛🚪","title":"Почини вместе со мной","task":{"3-5":"Дайте ребёнку закрутить большую крышку, застегнуть молнию или липучку. Пусть доведёт дело до конца без помощи.","6-8":"Найдите дома вещь, которую надо подтянуть или склеить. Ребёнок делает, вы только подсказываете.","9-12":"Выберите вместе небольшую домашнюю поломку. Ребёнок самостоятельно выясняет причину, предлагает способ и чинит. Вы отвечаете за безопасность."},"why":"Ребёнок чувствует, что своими руками можно починить настоящую вещь. Это добавляет уверенности.","tip":"Руки держите за спиной. Помогайте словами, а не делом.","need":{"3-5":"банка с большой крышкой, куртка с молнией, обувь на липучке","6-8":"вещь, которую надо подтянуть или склеить, отвёртка или клей","9-12":"небольшая домашняя поломка, нужные инструменты"},"steps":{"3-5":["Покажите один раз медленно, как закручивается крышка.","Ребёнок закручивает до конца без помощи.","То же с молнией и липучкой.","Скажите, что именно получилось: «Застёгнуто до самого верха, без помощи»."],"6-8":["Найдите вместе, что дома разболталось или отклеилось.","Ребёнок осматривает и говорит, что с вещью не так.","Чинит ребёнок, вы только подсказываете.","Проверьте вместе: держится?"],"9-12":["Выберите вместе одну поломку: скрипит дверца, шатается ручка.","Ребёнок выясняет причину и предлагает способ.","Вы проверяете, что это безопасно, и ребёнок чинит.","Через день проверьте, держится ли ремонт."]}},{"id":"inventor-1","scale":"inventor","art":"💧🍎⛵","title":"Тонет или плавает","task":{"3-5":"Таз с водой и 6 крупных предметов. Перед каждым спросите: утонет или поплывёт? Потом проверьте. Будьте рядом и вылейте воду сразу после игры.","6-8":"10 предметов. Ребёнок записывает прогноз для каждого, потом проверяет. Сколько прогнозов сбылось? Что общего у тех, что плавают?","9-12":"Сделайте из фольги лодку, которая выдержит больше всего монет. Три попытки с разной формой. Какая форма выиграла и почему?"},"why":"Прогноз, опыт, вывод: ребёнок проходит путь учёного в миниатюре.","tip":"Если прогноз не сбылся, порадуйтесь: «Вот это неожиданно! Почему так вышло?»","need":{"3-5":"таз с водой, 6 крупных предметов: губка, ложка, пластиковая крышка, яблоко, мяч, деревянный кубик","6-8":"таз с водой, 10 предметов, лист и карандаш","9-12":"фольга, таз с водой, монеты"},"steps":{"3-5":["Перед каждым предметом спросите: утонет или поплывёт?","Предмет в воду опускает ребёнок.","Разложите на две стороны: что плавает и что тонет.","Будьте рядом всё время. После игры сразу вылейте воду."],"6-8":["Ребёнок записывает или рисует прогноз для каждого предмета.","Проверяет по одному и ставит плюс или минус.","Посчитайте, сколько прогнозов сбылось.","Спросите: что общего у тех, что плавают?"],"9-12":["Задача: лодка из фольги, которая выдержит больше всего монет.","Три попытки с разной формой: плоская, с бортами, длинная.","Для каждой считайте монеты до затопления.","Какая форма выиграла и почему? Запишите ответ одной фразой."]}},{"id":"inventor-2","scale":"inventor","art":"🥛🧂🔍","title":"Что будет, если","task":{"3-5":"Смешайте воду с тем, что есть на кухне: соль, сахар, мука, масло. Что исчезло, а что нет? Пробовать на вкус ничего не нужно.","6-8":"Сода и уксус в стакане. Сначала прогноз, потом опыт. Что изменится, если соды взять вдвое больше?","9-12":"Придумайте свой вопрос «что будет, если…» про воду, лёд или магнит. Запишите прогноз, проведите опыт, запишите результат."},"why":"Ребёнок учится менять одно условие и смотреть, что изменилось. Так устроен любой эксперимент.","tip":"Вместо объяснений задавайте вопрос: «А если взять больше? А если теплее?»","need":{"3-5":"4 стакана воды, ложка, соль, сахар, мука, растительное масло","6-8":"стакан, поднос, сода, уксус, ложка","9-12":"вода, лёд или магнит на выбор, лист для записей"},"steps":{"3-5":["В каждый стакан ребёнок добавляет ложку одного продукта.","Размешайте и посмотрите: что исчезло, а что нет?","Найдите стакан, где получилось самое интересное.","Пробовать на вкус ничего не нужно. После опыта вылейте всё вместе."],"6-8":["Поставьте стакан на поднос. Ребёнок говорит прогноз: что будет?","Насыпьте ложку соды, уксус наливает взрослый.","Повторите с двумя ложками соды.","Что изменилось? Ребёнок объясняет своими словами."],"9-12":["Ребёнок придумывает свой вопрос «что будет, если…».","Записывает прогноз.","Проводит опыт. Вы следите за безопасностью.","Записывает результат и сравнивает с прогнозом."]}},{"id":"inventor-3","scale":"inventor","art":"📦💡♻️","title":"Новая жизнь вещи","task":{"3-5":"Возьмите пустую коробку. Чем она может быть? Придумайте три варианта и поиграйте в каждый.","6-8":"Одна прищепка. Придумайте 10 способов её использовать, кроме сушки белья. Лучший проверьте на деле.","9-12":"Выберите вещь, которую собирались выбросить. Придумайте из неё полезный предмет для дома и сделайте его."},"why":"Привычка видеть в обычной вещи много возможностей. С неё начинается изобретательность.","tip":"Принимайте все идеи, даже странные. Отбирать будете потом.","need":{"3-5":"пустая коробка","6-8":"одна прищепка, лист бумаги","9-12":"вещь, которую собирались выбросить, клей, скотч, ножницы"},"steps":{"3-5":["Спросите: чем может быть эта коробка?","Придумайте три варианта: машина, домик, шляпа.","Поиграйте в каждый по минуте.","Какой вариант понравился больше всего?"],"6-8":["Задача: 10 способов использовать прищепку, кроме сушки белья.","Ребёнок называет, вы записываете. Первые идеи будут простыми, дальше интереснее.","Выберите вместе лучшую.","Проверьте её на деле."],"9-12":["Выберите вещь: банка, коробка, старая футболка.","Ребёнок придумывает, каким полезным предметом для дома она станет.","Делает его. Вы помогаете только там, где нужен инструмент.","Найдите предмету место и пользуйтесь неделю."]}},{"id":"inventor-4","scale":"inventor","art":"🥄🍴🔢","title":"Найди закономерность","task":{"3-5":"Выложите ряд: ложка, вилка, ложка, вилка. Что дальше? Потом ряд придумывает ребёнок.","6-8":"Напишите ряд чисел: 2, 4, 6, 8. Что дальше? Затем 1, 2, 4, 7, 11. Потом ребёнок загадывает ряд вам.","9-12":"Ребёнок придумывает шифр (буква = число или значок) и пишет вам записку. Ваша задача: расшифровать. Потом меняетесь."},"why":"Умение замечать правило в ряду нужно в математике, музыке и программировании.","tip":"Когда ребёнок загадывает ряд вам, ошибитесь один раз нарочно. Пусть объяснит правило.","need":{"3-5":"4 ложки и 4 вилки (или кубики двух цветов)","6-8":"лист бумаги, карандаш","9-12":"бумага, ручка"},"steps":{"3-5":["Выложите ряд: ложка, вилка, ложка, вилка.","Спросите: что дальше? Ребёнок кладёт следующий предмет.","Усложните: две ложки, одна вилка.","Теперь ряд придумывает ребёнок, а продолжаете вы."],"6-8":["Напишите ряд: 2, 4, 6, 8. Что дальше?","Затем ряд сложнее: 1, 2, 4, 7, 11.","Попросите объяснить правило словами.","Ребёнок загадывает свой ряд вам."],"9-12":["Ребёнок придумывает шифр: буква равна числу или значку.","Пишет вам записку из одного предложения.","Вы расшифровываете. Ключ дайте только после трёх попыток.","Поменяйтесь ролями."]}},{"id":"inventor-5","scale":"inventor","art":"⚙️🔗🔔","title":"Машина для простого дела","task":{"3-5":"Как достать игрушку с полки, не вставая? Попробуйте верёвку, ложку, палку. Что сработало?","6-8":"Придумайте и нарисуйте машину, которая кормит кота или поливает цветок. Подпишите, что делает каждая часть.","9-12":"Соберите цепочку из 4 шагов: домино толкает шарик, шарик падает в стакан и так далее. Цель: в конце звенит колокольчик или падает ложка."},"why":"Ребёнок разбивает задачу на шаги и соединяет их в цепочку. Это инженерное и логическое мышление вместе.","tip":"Не исправляйте конструкцию сами. Спросите: «На каком шаге остановилось?»","need":{"3-5":"игрушка на невысокой полке, верёвка, большая ложка, палка","6-8":"лист бумаги, карандаши","9-12":"домино, шарик, стакан, книги, ложка или колокольчик"},"steps":{"3-5":["Задача: достать игрушку, не вставая с пола.","Попробуйте по очереди верёвку, ложку и палку.","Что сработало лучше всего?","Придумайте вместе ещё один способ."],"6-8":["Задача: придумать машину, которая кормит кота или поливает цветок.","Ребёнок рисует её целиком.","Подписывает, что делает каждая часть.","Рассказывает вам, как она работает, от начала до конца."],"9-12":["Задача: цепочка из 4 шагов, в конце звенит колокольчик или падает ложка.","Ребёнок собирает и проверяет каждый шаг отдельно.","Запуск целиком. Не получилось? Найдите шаг, где остановилось.","Снимите удачный запуск на телефон."]}},{"id":"storyteller-1","scale":"storyteller","art":"🧸📖✨","title":"История из трёх вещей","task":{"3-5":"Возьмите три игрушки. Начните: «Жил-был…». Ребёнок говорит, что случилось дальше.","6-8":"Три случайных предмета из комнаты. Ребёнок сочиняет историю, где все три важны. У истории есть начало, беда и конец.","9-12":"Три случайных слова из книги. Ребёнок за 10 минут пишет историю на полстраницы с неожиданным концом и читает её вслух."},"why":"Ребёнок строит сюжет: начало, трудность, развязка. Это основа связной речи и письма.","tip":"Не поправляйте сюжет. Помогайте вопросом: «И что случилось потом?»","need":{"3-5":"три игрушки","6-8":"три случайных предмета из комнаты","9-12":"книга, лист бумаги, ручка, таймер"},"steps":{"3-5":["Поставьте три игрушки перед ребёнком.","Начните: «Жил-был…» и назовите первую игрушку.","Ребёнок говорит, что случилось дальше. Вы добавляете по одной фразе по очереди.","Закончите вместе: чем всё кончилось?"],"6-8":["Ребёнок с закрытыми глазами выбирает три предмета.","Условие: в истории важны все три.","У истории есть начало, беда и конец. Ребёнок рассказывает вслух.","Перескажите историю ребёнку в двух фразах: так ли вы поняли?"],"9-12":["Откройте книгу наугад три раза и выпишите по одному слову.","За 10 минут ребёнок пишет историю на полстраницы с этими словами.","Условие: неожиданный конец.","Ребёнок читает вслух. Скажите, в каком месте вам стало интересно."]}},{"id":"storyteller-2","scale":"storyteller","art":"📚🐺🔀","title":"Другой конец","task":{"3-5":"Прочитайте знакомую сказку и остановитесь перед концом. Спросите: а как ещё могло закончиться?","6-8":"Ребёнок пересказывает любимую сказку, но злодей оказывается добрым. Что меняется?","9-12":"Ребёнок пересказывает известную историю от лица второстепенного героя. Что тот видел и чего не знал?"},"why":"Менять известный сюжет значит понимать, как он устроен. Так развивается гибкость мышления.","tip":"Спрашивайте «почему он так поступил?», а не «правильно ли это?».","need":{"3-5":"знакомая книжка со сказкой","6-8":"ничего не нужно","9-12":"ничего не нужно"},"steps":{"3-5":["Читайте сказку и остановитесь перед самым концом.","Спросите: а как ещё могло закончиться?","Примите любой вариант и продолжите его одной фразой.","Дочитайте настоящий конец. Какой нравится больше?"],"6-8":["Ребёнок выбирает любимую сказку.","Условие: злодей на самом деле добрый.","Ребёнок пересказывает сказку с этим изменением.","Обсудите: что поменялось для остальных героев?"],"9-12":["Выберите известную историю, книгу или фильм.","Ребёнок выбирает второстепенного героя.","Пересказывает события от его лица: что тот видел и чего не знал.","Спросите: кто в этой версии главный герой?"]}},{"id":"storyteller-3","scale":"storyteller","art":"🎤👵❓","title":"Интервью","task":{"3-5":"Ребёнок с «микрофоном» (ложкой) спрашивает вас: что тебе нравилось в детстве?","6-8":"Ребёнок готовит 5 вопросов бабушке, дедушке или вам про детство и берёт интервью. Потом рассказывает, что удивило.","9-12":"Ребёнок берёт интервью у взрослого о его профессии: 7 вопросов, без «да/нет». Потом пересказывает главное за одну минуту."},"why":"Ребёнок учится задавать вопросы и слушать ответ. Это половина умения разговаривать.","tip":"Отвечайте всерьёз и коротко. Интервью ведёт ребёнок, а не вы.","need":{"3-5":"большая ложка вместо микрофона","6-8":"лист бумаги, карандаш, бабушка, дедушка или вы","9-12":"блокнот, ручка, взрослый с интересной работой"},"steps":{"3-5":["Дайте ребёнку «микрофон».","Ребёнок спрашивает: что тебе нравилось делать в детстве?","Ответьте одной короткой историей.","Поменяйтесь: теперь вопрос задаёте вы."],"6-8":["Ребёнок готовит 5 вопросов про детство.","Берёт интервью лично или по телефону.","Можно рисовать или записывать главное.","Потом рассказывает вам, что удивило больше всего."],"9-12":["Ребёнок готовит 7 вопросов о профессии. Условие: на них нельзя ответить «да» или «нет».","Проводит интервью и делает пометки.","За одну минуту пересказывает вам главное.","Спросите: какой вопрос оказался самым удачным?"]}},{"id":"storyteller-4","scale":"storyteller","art":"🔤😄💬","title":"Новые слова","task":{"3-5":"Придумайте вместе смешное имя для каждой игрушки и объясните, почему её так зовут.","6-8":"Придумайте слово, которого нет, и что оно значит. Используйте его сегодня три раза в разговоре.","9-12":"Выберите в книге три незнакомых слова. Ребёнок сначала угадывает значение по тексту, потом проверяет и составляет с каждым фразу."},"why":"Игра со словами расширяет словарь и показывает, что язык можно придумывать, а не только учить.","tip":"Используйте новое слово сами. Ребёнку важно услышать его в вашей речи.","need":{"3-5":"3–4 игрушки","6-8":"ничего не нужно","9-12":"книга, лист бумаги"},"steps":{"3-5":["Возьмите первую игрушку и придумайте ей смешное имя.","Ребёнок объясняет, почему её так зовут.","Следующей игрушке имя придумывает ребёнок.","Познакомьте игрушки друг с другом по новым именам."],"6-8":["Придумайте вместе слово, которого нет.","Договоритесь, что оно значит.","Задача на день: использовать его три раза в разговоре.","Вечером посчитайте, кто сколько раз вспомнил."],"9-12":["Ребёнок находит в книге три незнакомых слова.","Сначала угадывает значение по соседним фразам.","Проверяет по словарю или у вас.","Составляет с каждым словом свою фразу."]}},{"id":"storyteller-5","scale":"storyteller","art":"📺🎙️🪟","title":"Репортаж с места","task":{"3-5":"Ребёнок рассказывает, что видит в окне, как диктор: «Вот едет красная машина…»","6-8":"Ребёнок ведёт минутный репортаж с ужина или прогулки: кто, что, где. Можно записать на телефон и послушать.","9-12":"Ребёнок готовит двухминутный выпуск новостей семьи за неделю: три новости, прогноз на выходные. Запишите и покажите родным."},"why":"Ребёнок описывает то, что видит, по порядку и понятно для слушателя. Это навык выступления.","tip":"Будьте зрителем: слушайте до конца и задайте один вопрос «из студии».","need":{"3-5":"окно","6-8":"телефон для записи (по желанию)","9-12":"лист бумаги, телефон для записи"},"steps":{"3-5":["Сядьте у окна вместе.","Покажите пример голосом диктора: «Вот едет красная машина…»","Теперь репортаж ведёт ребёнок, одну минуту.","Поблагодарите «корреспондента» и спросите, что было самым интересным."],"6-8":["Тема: ужин или прогулка.","Ребёнок минуту рассказывает: кто, что, где.","Запишите на телефон.","Послушайте вместе. Что стоит добавить в следующий раз?"],"9-12":["Ребёнок выбирает три новости семьи за неделю.","Добавляет прогноз на выходные.","Записывает двухминутный выпуск.","Покажите запись родным."]}},{"id":"artist-1","scale":"artist","art":"✏️🌀🐾","title":"Рисунок из каракули","task":{"3-5":"Нарисуйте каракулю. Ребёнок превращает её в зверя: добавляет глаза, лапы, хвост.","6-8":"Каждый рисует каракулю и отдаёт другому. Задача: превратить чужую каракулю в картинку и дать ей название.","9-12":"Пять случайных линий на листе. Ребёнок делает из них законченный рисунок, где ни одна линия не лишняя."},"why":"Ребёнок учится видеть образ в случайной форме. Так работает воображение художника и дизайнера.","tip":"Спрашивайте «что ты здесь видишь?», а не «что это?».","need":{"3-5":"лист бумаги, толстые фломастеры или мелки","6-8":"два листа, фломастеры","9-12":"лист бумаги, карандаш или ручка"},"steps":{"3-5":["Нарисуйте на листе одну каракулю.","Спросите: на кого она похожа?","Ребёнок добавляет глаза, лапы, хвост.","Придумайте зверю имя."],"6-8":["Каждый рисует каракулю на своём листе.","Поменяйтесь листами.","Задача: превратить чужую каракулю в картинку.","Дайте картинкам названия и покажите друг другу."],"9-12":["Нарисуйте на листе пять случайных линий.","Ребёнок делает из них законченный рисунок.","Условие: ни одна линия не лишняя.","Попросите показать, чем стала каждая линия."]}},{"id":"artist-2","scale":"artist","art":"🎨🔵🖌️","title":"Один цвет","task":{"3-5":"Назовите цвет. Соберите по дому всё такого цвета и выложите из находок картинку на полу.","6-8":"Нарисуйте картину только одним цветом и его оттенками. Как показать ночь, если у вас только синий?","9-12":"Сфотографируйте на телефон 7 предметов одного цвета так, чтобы снимки смотрелись как серия. Выберите лучший кадр и объясните почему."},"why":"Ограничение одним цветом заставляет искать оттенки и форму. Так тренируется глаз.","tip":"Обратите внимание на оттенки: «Смотри, этот синий темнее. Где он пригодится?»","need":{"3-5":"предметы одного цвета из дома","6-8":"лист бумаги, краски или карандаши одного цвета, вода","9-12":"телефон с камерой"},"steps":{"3-5":["Назовите цвет дня.","Соберите по дому всё такого цвета: игрушки, носки, крышки.","Выложите из находок картинку на полу.","Сфотографируйте её и разложите вещи по местам вместе."],"6-8":["Ребёнок выбирает один цвет.","Задача: нарисовать картину только им и его оттенками.","Спросите: как показать ночь, если есть только синий?","Найдите на рисунке самое светлое и самое тёмное место."],"9-12":["Ребёнок выбирает цвет.","Снимает 7 предметов этого цвета так, чтобы кадры смотрелись как серия.","Выбирает лучший кадр.","Объясняет, почему именно он."]}},{"id":"artist-3","scale":"artist","art":"🎵🖍️🌈","title":"Музыка на бумаге","task":{"3-5":"Включите быструю песню, потом медленную. Ребёнок рисует под каждую. Чем рисунки отличаются?","6-8":"Включите музыку без слов. Ребёнок рисует то, что слышит: линии, пятна, цвета. Потом рассказывает, где на рисунке громко.","9-12":"Два разных трека, два листа. Ребёнок передаёт настроение каждого только формой и цветом, без предметов. Вы угадываете, где какой."},"why":"Ребёнок переводит звук в линию и цвет. Это связывает слух, чувство и руку.","tip":"Не просите рисовать предметы. Здесь важны линии, пятна и настроение.","need":{"3-5":"два листа бумаги, мелки, две песни: быстрая и медленная","6-8":"лист бумаги, краски или фломастеры, музыка без слов","9-12":"два листа, краски или карандаши, два разных трека"},"steps":{"3-5":["Включите быструю песню. Ребёнок рисует под неё на первом листе.","Включите медленную. Второй лист.","Положите рисунки рядом.","Чем они отличаются? Покажите пальцем."],"6-8":["Включите музыку без слов.","Ребёнок рисует то, что слышит: линии, пятна, цвета.","После музыки спросите: где на рисунке громко, а где тихо?","Придумайте рисунку название."],"9-12":["Ребёнок слушает первый трек и передаёт настроение только формой и цветом, без предметов.","То же со вторым треком.","Вы угадываете, какой лист к какому треку.","Ребёнок объясняет свой выбор цвета."]}},{"id":"artist-4","scale":"artist","art":"🍂🌰🖼️","title":"Картина из находок","task":{"3-5":"Соберите на прогулке листья, палочки, шишки. Дома выложите из них лицо или зверя.","6-8":"Коллаж из старого журнала и находок с прогулки. Тема: «место, где я хочу оказаться».","9-12":"Соберите композицию из предметов на столе, как натюрморт. Подвигайте лампу: как меняется картина от света? Сфотографируйте лучший вариант."},"why":"Композиция из готовых предметов учит замечать форму, фактуру и то, как вещи сочетаются.","tip":"Спросите: «Что будет, если это передвинуть сюда?» и дайте попробовать.","need":{"3-5":"листья, палочки, шишки с прогулки, лист бумаги","6-8":"старый журнал, находки с прогулки, клей, лист бумаги, ножницы","9-12":"3–5 предметов, настольная лампа, телефон"},"steps":{"3-5":["Соберите на прогулке листья, палочки и шишки.","Дома разложите находки на столе.","Выложите вместе лицо или зверя.","Сфотографируйте. После игры вымойте руки."],"6-8":["Тема: место, где я хочу оказаться.","Ребёнок вырезает или вырывает картинки из журнала.","Сначала раскладывает на листе, потом клеит.","Рассказывает вам, что это за место."],"9-12":["Ребёнок собирает композицию из предметов на столе, как натюрморт.","Двигает лампу: сбоку, сверху, сзади.","Смотрит, как меняются тени и настроение.","Фотографирует лучший вариант."]}},{"id":"artist-5","scale":"artist","art":"🥔🟣💌","title":"Свой узор","task":{"3-5":"Печатайте краской пальцами, губкой или половинкой картофеля. Получится узор для открытки.","6-8":"Придумайте узор для своей футболки или кружки и нарисуйте его на бумаге в натуральную величину.","9-12":"Придумайте знак (логотип) для своей семьи: три наброска, один финальный. Объясните, что значит каждая деталь."},"why":"Повторяющийся узор учит ритму и аккуратности, а знак учит выражать идею коротко.","tip":"Повесьте готовую работу на видное место. Для ребёнка это значит больше слов.","need":{"3-5":"краска для пальчиков, губка, половинка картофеля, лист бумаги, клеёнка","6-8":"лист бумаги, фломастеры","9-12":"бумага, карандаш, фломастеры"},"steps":{"3-5":["Застелите стол клеёнкой.","Покажите отпечаток пальцем, губкой, картофелем.","Ребёнок печатает узор по всему листу.","Когда высохнет, сложите лист пополам: получится открытка."],"6-8":["Ребёнок выбирает: узор для футболки или для кружки.","Обводит на листе контур в натуральную величину.","Заполняет его узором.","Спросите: кому хочется подарить такую вещь?"],"9-12":["Задача: знак вашей семьи.","Три быстрых наброска, по минуте на каждый.","Ребёнок выбирает один и рисует финальный вариант.","Объясняет, что значит каждая деталь."]}},{"id":"explorer-1","scale":"explorer","art":"🔎🍃🪣","title":"Охота за находками","task":{"3-5":"На прогулке найдите: что-то круглое, что-то мягкое, что-то жёлтое, что-то шумное.","6-8":"Список из 8 находок на прогулку: лист с зубчиками, след, что-то старше вас, что-то, чего вчера не было.","9-12":"Ребёнок самостоятельно составляет список из 10 находок для вас и ведёт маршрут. По дороге фотографирует самое странное, что заметит."},"why":"Поиск по признаку тренирует внимание и умение замечать детали вокруг.","tip":"Не показывайте находку сами. Сужайте круг: «Посмотри ниже. Теплее!»","need":{"3-5":"прогулка, пакет или ведёрко","6-8":"список из 8 находок на листке, карандаш","9-12":"листок, ручка, телефон с камерой"},"steps":{"3-5":["Назовите четыре задания: что-то круглое, что-то мягкое, что-то жёлтое, что-то шумное.","Ищите по одному. Ребёнок показывает находку.","Спросите про каждую: какая она на ощупь?","Дома вспомните все четыре находки."],"6-8":["Напишите список: лист с зубчиками, след, что-то старше вас, что-то, чего вчера не было, и ещё четыре своих.","На прогулке ребёнок ищет и вычёркивает.","Про спорные находки пусть докажет, что подходит.","Какая находка была самой трудной?"],"9-12":["Ребёнок самостоятельно составляет список из 10 находок для вас.","Ведёт маршрут, вы ищете.","По дороге фотографирует самое странное, что заметит.","Дома посмотрите фото и выберите находку дня."]}},{"id":"explorer-2","scale":"explorer","art":"🗺️❌🧸","title":"Карта комнаты","task":{"3-5":"Спрячьте игрушку и подсказывайте: «рядом с кроватью», «под столом». Потом прячет ребёнок.","6-8":"Ребёнок рисует карту комнаты сверху и отмечает крестиком спрятанный клад. Вы ищете по карте.","9-12":"Ребёнок рисует карту пути от дома до школы или магазина по памяти. Потом вы проходите маршрут и исправляете карту."},"why":"Карта учит представлять пространство сверху и переводить его на бумагу.","tip":"Ищите по карте честно. Если карта неточная, пусть ребёнок своими глазами увидит, где сбой.","need":{"3-5":"любимая игрушка","6-8":"лист бумаги, карандаш, маленький «клад»","9-12":"лист бумаги, карандаш"},"steps":{"3-5":["Спрячьте игрушку в комнате, пока ребёнок не смотрит.","Подсказывайте словами: «рядом с кроватью», «под столом».","Игрушка найдена? Теперь прячет ребёнок и подсказывает вам.","Сыграйте три круга."],"6-8":["Ребёнок рисует комнату сверху: кровать, стол, дверь.","Прячет клад и ставит на карте крестик.","Вы ищете только по карте.","Поменяйтесь: карту рисуете вы."],"9-12":["Ребёнок по памяти рисует путь от дома до школы или магазина.","Отмечает повороты и три ориентира.","Пройдите маршрут вместе с картой в руках.","Исправьте на карте то, что не совпало."]}},{"id":"explorer-3","scale":"explorer","art":"🤫👂🐦","title":"Пять минут тишины","task":{"3-5":"Сядьте у окна на 2 минуты. Что вы слышите? Считайте звуки на пальцах.","6-8":"5 минут во дворе молча. Потом каждый называет три вещи, которые заметил, а другой нет.","9-12":"10 минут наблюдения за одним местом (кормушка, перекрёсток, муравейник). Ребёнок записывает, что происходит, и находит одну закономерность."},"why":"Тихое наблюдение учит замечать то, что обычно пропускаешь. Это главный инструмент исследователя.","tip":"Молчите вместе с ребёнком. Ваш пример работает лучше просьбы «сиди тихо».","need":{"3-5":"окно или скамейка","6-8":"двор или парк, таймер на 5 минут","9-12":"блокнот, ручка, место для наблюдения: кормушка, перекрёсток, муравейник"},"steps":{"3-5":["Сядьте рядом на 2 минуты.","Закройте глаза и слушайте.","Каждый новый звук считайте на пальцах.","Какой звук был самым тихим?"],"6-8":["Договоритесь: 5 минут молчим и смотрим.","Каждый запоминает то, что заметил.","Потом по очереди называйте по три вещи.","Побеждает тот, кто заметил то, чего не видел другой."],"9-12":["Ребёнок выбирает одно место и 10 минут наблюдает.","Записывает, что происходит и когда.","Ищет одну закономерность: что повторяется?","Рассказывает вам вывод и как его проверить завтра."]}},{"id":"explorer-4","scale":"explorer","art":"🧦🔴🗂️","title":"Моя коллекция","task":{"3-5":"Разложите большие крышки, носки или кубики по кучкам: по цвету, потом по размеру.","6-8":"Соберите 10 листьев или камней. Ребёнок самостоятельно решает, как их разделить на группы, и объясняет правило.","9-12":"Начните коллекцию на неделю: каждый день одна находка с подписью, где и когда найдена. В конце недели сделайте витрину."},"why":"Сортировка учит находить признак и объяснять правило. С этого начинается любая классификация.","tip":"Не подсказывайте правило. Спросите: «Почему эти вместе?»","need":{"3-5":"большие крышки, носки или кубики","6-8":"10 листьев или камней с прогулки","9-12":"коробка или полка, бумажки для подписей"},"steps":{"3-5":["Высыпьте предметы на пол.","Разложите вместе по цвету.","Смешайте и разложите по размеру: большие и маленькие.","Пусть ребёнок придумает третий способ."],"6-8":["Разложите находки на столе.","Ребёнок самостоятельно решает, как разделить их на группы.","Объясняет правило.","Попросите разделить ещё раз по другому правилу."],"9-12":["Ребёнок выбирает тему коллекции на неделю.","Каждый день одна находка с подписью: где и когда найдена.","В конце недели делает из них выставку.","Проводит для семьи экскурсию на две минуты."]}},{"id":"explorer-5","scale":"explorer","art":"❓📗🔭","title":"Вопрос дня","task":{"3-5":"Ребёнок задаёт один вопрос «почему». Ищете ответ вместе: в книге, на улице или опытом.","6-8":"Ребёнок выбирает животное и находит о нём три факта, которых вы не знали. Проверьте, правда ли не знали.","9-12":"Ребёнок выбирает вопрос, на который нет быстрого ответа, находит два разных источника и рассказывает, в чём они расходятся."},"why":"Ребёнок учится самостоятельно искать ответ и проверять его.","tip":"Скажите честно «я не знаю, давай выясним». Это лучший пример для исследователя.","need":{"3-5":"детская энциклопедия или окно","6-8":"книга о животных или поиск вместе со взрослым","9-12":"два источника: книга и сайт или два сайта"},"steps":{"3-5":["Ребёнок задаёт один вопрос «почему».","Скажите: давай выясним вместе.","Ищите ответ в книге, на улице или простым опытом.","Попросите рассказать ответ другому взрослому."],"6-8":["Ребёнок выбирает животное.","Находит о нём три факта, которых вы не знали.","Рассказывает вам.","Честно скажите, какие из них вы правда не знали."],"9-12":["Ребёнок выбирает вопрос, на который нет быстрого ответа.","Находит два разных источника.","Сравнивает: в чём они сходятся и в чём расходятся?","Рассказывает, какому верит больше и почему."]}},{"id":"leader-1","scale":"leader","art":"⏱️👑🎲","title":"Капитан на 15 минут","task":{"3-5":"15 минут ребёнок главный: выбирает игру и говорит, кто что делает. Вы слушаетесь.","6-8":"Ребёнок планирует семейную прогулку на час: куда идём, что берём, кто за что отвечает.","9-12":"Ребёнок организует семейный вечер: программа, роли для каждого, бюджет, который назовёте вы. После вечера обсудите, что получилось."},"why":"Ребёнок пробует отвечать за других: решать, распределять, договариваться.","tip":"Слушайтесь всерьёз. Если решение неудачное, пусть результат скажет за себя.","need":{"3-5":"таймер на 15 минут","6-8":"лист бумаги, карандаш","9-12":"лист бумаги, бюджет, который назовёте вы"},"steps":{"3-5":["Объявите: 15 минут командуешь ты.","Ребёнок выбирает игру.","Говорит, кто что делает. Вы слушаетесь.","Когда таймер прозвенит, поблагодарите «капитана»."],"6-8":["Задача: спланировать семейную прогулку на час.","Ребёнок решает, куда идём и что берём.","Назначает, кто за что отвечает.","Сходите по плану ребёнка. Что сработало?"],"9-12":["Ребёнок организует семейный вечер.","Составляет программу и роли для каждого.","Укладывается в бюджет.","После вечера обсудите: что получилось и что стоит сделать иначе."]}},{"id":"leader-2","scale":"leader","art":"⚽📋🎲","title":"Новая игра","task":{"3-5":"Придумайте игру с мячом и одним правилом. Поиграйте. Ребёнок добавляет второе правило.","6-8":"Ребёнок придумывает игру с тремя правилами и объясняет её семье. Если кто-то не понял, правило надо сказать проще.","9-12":"Ребёнок придумывает настольную игру на листе бумаги: цель, ходы, как выиграть. Сыграйте и вместе исправьте одно слабое правило."},"why":"Придумать правило и объяснить его другим значит учиться управлять без крика.","tip":"Если правило непонятно, не додумывайте за ребёнка. Скажите: «Мне непонятно. Объясни проще».","need":{"3-5":"мяч","6-8":"любые игрушки или мяч","9-12":"лист бумаги, карандаш, кубик, фишки"},"steps":{"3-5":["Придумайте игру с мячом и одним правилом. Например: катаем только сидя.","Поиграйте две минуты.","Ребёнок добавляет второе правило.","Сыграйте по новым правилам."],"6-8":["Ребёнок придумывает игру с тремя правилами.","Объясняет её семье.","Кто-то не понял? Правило надо сказать проще.","Сыграйте один раунд."],"9-12":["Ребёнок рисует настольную игру: цель, ходы, как выиграть.","Сыграйте партию.","Найдите вместе одно слабое правило.","Исправьте его и сыграйте ещё раз."]}},{"id":"leader-3","scale":"leader","art":"🍎🍌💬","title":"Убеди меня","task":{"3-5":"Ребёнок выбирает между двумя вещами (яблоко или банан) и говорит почему. Одной причины достаточно.","6-8":"Ребёнок хочет что-то изменить дома (время сна, меню). Пусть назовёт три причины. Хорошие доводы принимаются.","9-12":"Спор по правилам: ребёнок 2 минуты защищает мнение, потом 2 минуты защищает противоположное. Какая сторона оказалась сильнее?"},"why":"Ребёнок учится добиваться своего доводами, а не настойчивостью.","tip":"Заранее решите, на что вы готовы согласиться. Последнее слово остаётся за вами.","need":{"3-5":"два предмета на выбор: яблоко и банан, две книги","6-8":"ничего не нужно","9-12":"таймер"},"steps":{"3-5":["Предложите выбор из двух.","Ребёнок выбирает и говорит почему.","Одной причины достаточно.","Повторите довод ребёнка вслух: «Ты выбираешь банан, потому что он сладкий»."],"6-8":["Ребёнок называет одну вещь, которую хочет изменить дома.","Приводит три причины.","Вы отвечаете на каждую по существу.","Хорошие доводы принимаются. Решение за вами, и вы объясняете его."],"9-12":["Выберите тему спора.","Две минуты ребёнок защищает своё мнение.","Две минуты защищает противоположное.","Какая сторона оказалась сильнее и почему?"]}},{"id":"leader-4","scale":"leader","art":"🤝🧺⭐","title":"Помощник капитана","task":{"3-5":"Сегодня командуете вы, а ребёнок помогает: по вашей просьбе делает три дела. Поблагодарите за каждое.","6-8":"В игре ребёнок сегодня не водит, а помогает младшему или вам. Потом спросите: что было трудно?","9-12":"Ребёнок помогает другому человеку довести его идею до конца, не меняя её на свою. Потом обсудите, где хотелось перехватить."},"why":"Лидеру важно уметь быть вторым: слушать, помогать и не перехватывать.","tip":"Благодарите за конкретное дело: «Благодаря тебе всё принесено сразу, и мы успели».","need":{"3-5":"три простых дела по дому","6-8":"любая игра","9-12":"чужая идея: проект брата, сестры или ваш"},"steps":{"3-5":["Объявите: сегодня командую я, а ты помогаешь.","Попросите о первом деле.","Поблагодарите и назовите второе, потом третье.","Скажите, чем эта помощь вам пригодилась."],"6-8":["В игре ребёнок сегодня не водит.","Ребёнок помогает младшему или вам.","Сыграйте 10 минут.","Спросите: что было трудно? Что понравилось?"],"9-12":["Ребёнок выбирает, кому поможет.","Задача: довести чужую идею до конца, не меняя её на свою.","Работает 10 минут.","Обсудите: в какой момент хотелось сделать по-своему?"]}},{"id":"leader-5","scale":"leader","art":"🪙🛒🍪","title":"Маленькое дело","task":{"3-5":"Игра в магазин: ребёнок продавец, вы покупатель. Продавец называет цену и считает «монеты» из бумаги.","6-8":"Ребёнок решает, что можно сделать для соседей или родных (открытки, печенье), и раздаёт задачи семье.","9-12":"Ребёнок придумывает маленькое дело на выходные: что делаем, для кого, сколько стоит. Считает расходы и результат."},"why":"Маленькое дело с ценой и результатом учит считать, планировать и думать о других.","tip":"Пусть ребёнок считает без подсказок. Ошибку в расчёте найдите вместе.","need":{"3-5":"игрушки-«товары», бумажные «монеты»","6-8":"бумага, карандаши или продукты для печенья","9-12":"лист бумаги, калькулятор"},"steps":{"3-5":["Вырежьте заранее 10 бумажных монет.","Ребёнок раскладывает товары в роли продавца.","Вы покупаете. Продавец называет цену и считает монеты.","Поменяйтесь ролями."],"6-8":["Ребёнок решает, что сделать для соседей или родных.","Раздаёт задачи семье.","Делаете вместе по плану ребёнка.","Результат вручает ребёнок."],"9-12":["Ребёнок придумывает маленькое дело на выходные.","Пишет: что делаем, для кого, сколько стоит.","Считает расходы.","После выходных подводит итог."]}},{"id":"helper-1","scale":"helper","art":"😀😢😮","title":"Кто что чувствует","task":{"3-5":"Покажите лицом: радость, грусть, злость, удивление. Ребёнок угадывает и повторяет.","6-8":"Откройте книгу на картинке. Что чувствует каждый герой? По чему это видно?","9-12":"Посмотрите минуту фильма без звука. Ребёнок объясняет, что чувствуют герои и что, скорее всего, было сказано."},"why":"Ребёнок учится читать чувства по лицу и позе. Это основа эмпатии.","tip":"Называйте чувства и про себя тоже: «Я сейчас без сил, это видно по плечам».","need":{"3-5":"зеркало (по желанию)","6-8":"книга с картинками","9-12":"минута из фильма без звука"},"steps":{"3-5":["Покажите лицом радость. Ребёнок угадывает.","Потом грусть, злость, удивление.","Ребёнок повторяет каждое выражение.","Теперь показывает ребёнок, а угадываете вы."],"6-8":["Откройте книгу на картинке с несколькими героями.","Что чувствует каждый?","По чему это видно: лицо, руки, поза?","Что сказал бы герой, если бы мог?"],"9-12":["Включите минуту фильма без звука.","Ребёнок объясняет, что чувствуют герои.","Говорит, что, скорее всего, было сказано.","Включите со звуком и сравните."]}},{"id":"helper-2","scale":"helper","art":"🎁🤫💛","title":"Тайное доброе дело","task":{"3-5":"Вместе сделайте сюрприз кому-то дома: рисунок под подушку или накрытый стол.","6-8":"Ребёнок выбирает человека и делает для него одно доброе дело так, чтобы тот не знал, кто это сделал.","9-12":"Ребёнок замечает, кому из близких сейчас непросто, и самостоятельно придумывает, чем помочь. Вы только обеспечиваете нужное."},"why":"Доброе дело без награды учит заботиться ради другого, а не ради похвалы.","tip":"Сохраните тайну. Не рассказывайте, кто сделал сюрприз.","need":{"3-5":"бумага, мелки или посуда для стола","6-8":"ничего не нужно","9-12":"то, что понадобится для помощи"},"steps":{"3-5":["Выберите, кому дома сделаете сюрприз.","Решите что: рисунок под подушку или накрытый стол.","Сделайте вместе, тихо.","Посмотрите издалека, как человек обрадуется."],"6-8":["Ребёнок выбирает человека.","Придумывает одно доброе дело для него.","Делает так, чтобы тот не узнал, кто это сделал.","Вечером расскажет вам о своих чувствах."],"9-12":["Ребёнок замечает, кому из близких сейчас непросто.","Самостоятельно придумывает, чем помочь.","Вы только даёте нужное.","Потом спросите: как стало понятно, что человеку нужна помощь?"]}},{"id":"helper-3","scale":"helper","art":"📕📗☝️","title":"А чего хочу я","task":{"3-5":"Дайте выбор из двух: какую книгу читаем, какую чашку берём. Ребёнок выбирает без подсказок и вслух.","6-8":"Сегодня ребёнок три раза говорит «я хочу…» и один раз вежливо говорит «нет». Потренируйтесь в игре.","9-12":"Разберите случай, когда ребёнок согласился, хотя не хотел. Как можно было отказать, не обидев? Отрепетируйте фразу."},"why":"Чуткому ребёнку важно уметь слышать и свои желания, а не только чужие.","tip":"Примите детское «нет» спокойно. Так ребёнок узнаёт, что отказ не рушит отношения.","need":{"3-5":"две книги или две чашки","6-8":"ничего не нужно","9-12":"ничего не нужно"},"steps":{"3-5":["Предложите выбор из двух вещей.","Ребёнок выбирает без подсказок и говорит вслух: «Я хочу эту».","Повторите выбор три раза за день в разных делах.","Не переспрашивайте и не предлагайте третий вариант."],"6-8":["Сыграйте в игру: вы предлагаете, ребёнок отвечает.","Задача: три раза сказать «я хочу…».","И один раз вежливо сказать «нет».","Скажите, что вам понравился такой вежливый отказ."],"9-12":["Вспомните случай, когда ребёнок согласился, хотя не хотел.","Обсудите: что мешало отказать?","Придумайте фразу, которая не обидит.","Отрепетируйте её вслух два раза."]}},{"id":"helper-4","scale":"helper","art":"💌🖍️🙏","title":"Письмо спасибо","task":{"3-5":"Ребёнок рисует открытку человеку, который недавно помог. Вы подписываете словами ребёнка.","6-8":"Ребёнок пишет три предложения спасибо учителю, тренеру или соседу: за что именно и что это изменило.","9-12":"Ребёнок пишет письмо человеку, которого давно не благодарил, и самостоятельно решает, как его передать."},"why":"Благодарность словами учит замечать, что для тебя делают другие.","tip":"Помогите вспомнить конкретное дело: «За что именно спасибо?»","need":{"3-5":"бумага, мелки","6-8":"лист бумаги, ручка","9-12":"бумага, ручка, конверт"},"steps":{"3-5":["Спросите: кто тебе недавно помог?","Ребёнок рисует открытку этому человеку.","Вы подписываете словами ребёнка, ничего не меняя.","Вручите вместе."],"6-8":["Ребёнок выбирает: учитель, тренер или сосед.","Пишет три предложения: за что спасибо и что это изменило.","Вы не правите текст, только ошибки, если ребёнок попросит.","Записку передаёт ребёнок."],"9-12":["Ребёнок вспоминает человека, которого давно не благодарил.","Пишет ему письмо.","Самостоятельно решает, как передать: лично, почтой, сообщением.","Передаёт на этой неделе."]}},{"id":"helper-5","scale":"helper","art":"🧑‍🏫🪥🧥","title":"Учитель на 10 минут","task":{"3-5":"Ребёнок учит игрушку или вас тому, что умеет: чистить зубы, надевать куртку.","6-8":"Ребёнок учит вас или младшего одной вещи, которую умеет хорошо. Вы стараетесь и иногда ошибаетесь.","9-12":"Ребёнок готовит десятиминутный урок для семьи по теме, в которой разбирается: объяснение, пример, вопрос на проверку."},"why":"Объясняя другим, ребёнок глубже понимает тему и чувствует свою умелость.","tip":"Будьте старательным учеником и иногда ошибайтесь. Пусть ребёнок вас поправит.","need":{"3-5":"игрушка, зубная щётка или куртка","6-8":"то, что ребёнок умеет хорошо","9-12":"лист бумаги для плана"},"steps":{"3-5":["Спросите: что ты умеешь без помощи?","Ребёнок учит игрушку или вас: чистить зубы, надевать куртку.","Сделайте ошибку. Пусть покажет, как правильно.","Поблагодарите учителя."],"6-8":["Ребёнок выбирает одно умение.","Учит вас или младшего по шагам.","Вы стараетесь и один раз ошибаетесь.","В конце покажите, чему научились."],"9-12":["Ребёнок выбирает тему, в которой разбирается.","Готовит урок на 10 минут: объяснение, пример, вопрос на проверку.","Проводит его для семьи.","Каждый называет одну вещь, которую узнал."]}},{"id":"mover-1","scale":"mover","art":"🪑🧗🏁","title":"Полоса препятствий","task":{"3-5":"Подушки, стул, верёвка на полу: перешагнуть, проползти, пройти по линии. Три круга.","6-8":"Ребёнок самостоятельно строит дома полосу из 5 препятствий и проходит её на время. Вторая попытка быстрее?","9-12":"Ребёнок строит полосу из 6 этапов и придумывает правила штрафа. Проходите оба на время, три попытки, записываете результаты."},"why":"Полоса препятствий развивает координацию и умение планировать движение.","tip":"Уберите с пути острые углы и скользкие коврики. Хвалите за аккуратность, а не только за скорость.","need":{"3-5":"подушки, стул, верёвка или пояс","6-8":"подушки, стулья, верёвка, секундомер","9-12":"домашние предметы, секундомер, лист для записи"},"steps":{"3-5":["Положите верёвку на пол линией, рядом подушки и стул.","Покажите путь: перешагнуть, проползти под стулом, пройти по линии.","Ребёнок проходит три круга.","На последнем круге идите вместе."],"6-8":["Ребёнок самостоятельно строит полосу из 5 препятствий.","Проходит её на время.","Вторая попытка: получится быстрее?","Спросите, какое препятствие самое трудное."],"9-12":["Ребёнок строит полосу из 6 этапов.","Придумывает правила штрафа за ошибку.","Проходите оба, по три попытки.","Запишите результаты. Чей прогресс больше?"]}},{"id":"mover-2","scale":"mover","art":"🎶🕺🧊","title":"Замри","task":{"3-5":"Музыка играет, все танцуют. Музыка стоп, все замирают. Кто простоит, не шевелясь, до счёта 5?","6-8":"Танцы и «замри» на одной ноге. Каждый раунд стоять на 2 секунды дольше.","9-12":"«Замри» с заданием: по команде принять позу (планка, ласточка, присед) и держать 20 секунд. Ребёнок придумывает позы для вас."},"why":"Игра «замри» тренирует умение остановиться по сигналу. Это основа самоконтроля.","tip":"Играйте вместе. Ребёнку важно видеть, что замереть трудно и вам.","need":{"3-5":"музыка","6-8":"музыка","9-12":"музыка, таймер"},"steps":{"3-5":["Включите музыку и танцуйте вместе.","Остановите музыку: все замирают.","Считайте вслух до 5.","Сыграйте пять раундов."],"6-8":["Танцуйте под музыку.","По остановке замрите на одной ноге.","Каждый раунд стойте на 2 секунды дольше.","До какого счёта дошли?"],"9-12":["По остановке музыки нужно принять позу: планка, ласточка или присед.","Держать 20 секунд.","Позы для вас придумывает ребёнок.","Пять раундов, потом поменяйтесь."]}},{"id":"mover-3","scale":"mover","art":"🤹⚽📈","title":"Новый трюк","task":{"3-5":"Подбросить мягкий мяч и поймать двумя руками. Потом хлопнуть, пока мяч в воздухе.","6-8":"Выберите трюк: 10 прыжков на скакалке подряд или набить воздушный шар 20 раз. Пять минут практики, потом зачёт. Лопнувший шар убирает взрослый.","9-12":"Ребёнок выбирает навык на неделю (жонглирование двумя мячами, стойка у стены, чеканка). Сегодня первый замер и план."},"why":"Ребёнок видит, что навык растёт от практики. Это меняет отношение к трудному.","tip":"Считайте попытки, а не ошибки: «Это была двенадцатая, стало ровнее».","need":{"3-5":"мягкий мяч","6-8":"скакалка или воздушный шар","9-12":"два мяча или стена, лист для записи"},"steps":{"3-5":["Ребёнок подбрасывает мяч и ловит двумя руками.","Пять раз подряд.","Усложните: хлопнуть, пока мяч в воздухе.","Сколько хлопков получилось?"],"6-8":["Выберите трюк: 10 прыжков подряд или набить шар 20 раз.","Пять минут практики.","Потом зачёт: считайте вслух.","Лопнувший шар убирает взрослый."],"9-12":["Ребёнок выбирает навык на неделю: жонглирование, стойка у стены, чеканка.","Сегодня первый замер: сколько получается сейчас.","Составляет план: 5 минут в день.","Повесьте лист с результатом на видное место."]}},{"id":"mover-4","scale":"mover","art":"🐻🔤🤸","title":"Буквы телом","task":{"3-5":"Покажите телом зверей: как идёт медведь, прыгает заяц, ползёт змея. Ребёнок угадывает и повторяет.","6-8":"Ребёнок показывает телом буквы своего имени, вы угадываете. Потом показываете слово вдвоём.","9-12":"Таблица умножения в движении: ответ надо не сказать, а пропрыгать или отбить мячом. 10 примеров на скорость."},"why":"Буквы и числа, показанные телом, учить веселее.","tip":"Смейтесь вместе. Чем смешнее поза, тем лучше запомнится.","need":{"3-5":"свободное место","6-8":"свободное место","9-12":"мяч, таймер"},"steps":{"3-5":["Покажите, как идёт медведь.","Ребёнок угадывает и повторяет.","Потом заяц и змея.","Теперь зверя загадывает ребёнок."],"6-8":["Ребёнок показывает телом первую букву своего имени.","Вы угадываете.","Потом показывает остальные буквы.","Покажите короткое слово вдвоём."],"9-12":["Вы называете пример из таблицы умножения.","Ответ надо пропрыгать или отбить мячом.","Десять примеров на скорость.","Поменяйтесь: примеры задаёт ребёнок."]}},{"id":"mover-5","scale":"mover","art":"🏃🧸😌","title":"Тихая минута после бега","task":{"3-5":"Две минуты побегайте и попрыгайте. Потом лягте на спину и положите игрушку на живот: как она качается?","6-8":"5 минут активной игры, затем 5 минут спокойного дела (пазл, рисунок). Заметьте вместе: легче сидеть после движения?","9-12":"Ребёнок проверяет на себе: читает 10 минут после разминки и 10 минут без неё. Когда запомнилось больше?"},"why":"Ребёнок на себе замечает, что после движения легче сосредоточиться. Этим можно пользоваться каждый день.","tip":"Используйте вывод: перед уроками или чтением дайте пять минут подвигаться.","need":{"3-5":"мягкая игрушка, коврик","6-8":"пазл или бумага и карандаши","9-12":"книга, таймер"},"steps":{"3-5":["Две минуты бегайте и прыгайте вместе.","Лягте на спину.","Положите ребёнку на живот игрушку.","Смотрите вместе, как она качается от дыхания."],"6-8":["Пять минут активной игры.","Пять минут спокойного дела: пазл или рисунок.","Спросите: легко ли сидеть сейчас?","Сравните с тем, как бывает без разминки."],"9-12":["Ребёнок читает 10 минут после разминки.","Пересказывает, что запомнилось.","На другой день читает 10 минут без разминки.","Сравнивает: когда запомнилось больше?"]}},{"id":"builder-6","scale":"builder","art":"🥄📄🎯","title":"Катапульта из ложки","why":"Ребёнок знакомится с рычагом: небольшое изменение опоры меняет силу и дальность.","tip":"Запускаем только мягкие комочки бумаги и только в сторону от людей.","need":{"3-5":"пластиковая или деревянная ложка, комочки бумаги, миска","6-8":"линейка, карандаш, комочки бумаги, листок","9-12":"линейка, ластик или карандаш, комочки бумаги, рулетка, листок"},"steps":{"3-5":["Скомкайте вместе пять бумажных шариков.","Положите шарик в ложку, ложку на край стола. Вы придерживаете ложку посередине, ребёнок хлопает по ручке.","Поставьте миску в шаге от стола. Получится попасть?","Посчитайте попадания из пяти."],"6-8":["Положите линейку на карандаш, как качели. На один край шарик.","Ребёнок нажимает на другой край и смотрит, куда улетел шарик.","Сдвиньте карандаш ближе к шарику, потом дальше. Три запуска на каждое положение.","Где шарик летит дальше всего? Пусть объяснит своими словами."],"9-12":["Задача: найти положение опоры для самого дальнего запуска.","Ребёнок выбирает три положения и делает по три запуска.","Записывает дальность в таблицу.","Формулирует вывод одной фразой и проверяет его четвёртым положением."]}},{"id":"builder-7","scale":"builder","art":"🪑🛋️⛺","title":"Шалаш из пледа","why":"Шалаш учит строить каркас: что держит, что накрывает и где слабое место.","tip":"Не поправляйте провисшую крышу. Спросите: «Что её держит? Чего не хватает?»","need":{"3-5":"два стула, плед, подушки","6-8":"стулья, пледы, прищепки, подушки","9-12":"пледы, прищепки, стулья, верёвка, лист бумаги"},"steps":{"3-5":["Поставьте стулья спинками друг к другу на расстоянии шага.","Накройте вместе пледом.","Ребёнок выбирает, где вход, и устраивает внутри место подушками.","Заберитесь внутрь вдвоём и прочитайте одну книжку."],"6-8":["Задача: шалаш, в котором помещаются двое.","Ребёнок выбирает опоры и крепит плед прищепками.","Проверка: залезьте вдвоём. Крыша держится?","Найдите слабое место и укрепите его."],"9-12":["Сначала план: две «комнаты» и вход.","Ребёнок строит по плану из того, что есть дома.","Испытание: пять минут внутри вдвоём, ничего не поправляя.","Что стоит изменить в плане в следующий раз?"]}},{"id":"builder-8","scale":"builder","art":"✈️📄📏","title":"Самолётик-рекордсмен","why":"Ребёнок меняет одну деталь и замеряет результат. Так работает инженер-испытатель.","tip":"Запускайте вдоль коридора, не в сторону людей. Меняйте только одну деталь за раз.","need":{"3-5":"два листа бумаги","6-8":"три листа бумаги, листок для записи","9-12":"бумага, скрепка, рулетка, листок"},"steps":{"3-5":["Сложите самолётик на глазах у ребёнка, медленно.","Ребёнок запускает его три раза.","Измерьте шагами самый дальний полёт.","Пусть раскрасит крылья и запустит ещё раз."],"6-8":["Сложите вместе две разные модели: узкую и широкую.","По три запуска каждой. Дальность меряем шагами.","Какая летит дальше? А какая ровнее?","Ребёнок придумывает моделям названия и записывает рекорд."],"9-12":["Ребёнок складывает одну модель и делает три контрольных запуска.","Меняет одну деталь: скрепка на носу или загнутые края крыльев.","Снова три запуска, результаты в таблицу.","Вывод: что помогло, что помешало и почему."]}},{"id":"inventor-6","scale":"inventor","art":"🔦🧸👤","title":"Опыты с тенью","why":"Ребёнок находит связь между расстоянием до света и размером тени. Это первый шаг к пониманию зависимостей.","tip":"Не объясняйте заранее. Спросите: «Как сделать тень больше?» и дайте попробовать.","need":{"3-5":"фонарик, игрушка, стена","6-8":"фонарик, игрушка, лист бумаги, карандаш","9-12":"фонарик, предмет, линейка, листок"},"steps":{"3-5":["Выключите верхний свет и посветите фонариком на игрушку у стены.","Найдите вместе тень.","Придвиньте фонарик ближе, потом дальше. Что стало с тенью?","Ребёнок своими руками делает тень-великана и тень-малыша."],"6-8":["Прикрепите лист к стене. Ребёнок ставит игрушку и светит.","Обведите тень карандашом.","Задача: сделать тень в два раза больше. Что надо подвинуть?","Обведите новую тень и сравните."],"9-12":["Ребёнок ставит фонарик на трёх расстояниях от предмета.","Каждый раз измеряет высоту тени и записывает.","Ищет правило: что происходит с тенью, когда свет ближе?","Проверяет правило на четвёртом расстоянии."]}},{"id":"inventor-7","scale":"inventor","art":"🧊🧂⏱️","title":"Спасти льдинку","why":"Ребёнок сравнивает условия и видит, что на результат влияет причина, которую можно найти.","tip":"Попросите прогноз до опыта. Не сбылся? Это самое интересное.","need":{"3-5":"два кубика льда, две тарелки","6-8":"три кубика льда, три блюдца, соль, тёплая вода","9-12":"кубики льда, фольга, ткань, бумага, коробочка, часы"},"steps":{"3-5":["Положите по кубику льда на две тарелки.","Одну поставьте в тёплое место, другую в прохладное.","Спросите: какой растает первым?","Проверьте через пять и десять минут: какой стал меньше? Лёд ребёнок в рот не берёт."],"6-8":["Ребёнок говорит прогноз: какой кубик растает первым.","Первый посыпает солью, второй поливает тёплой водой, третий не трогает.","Наблюдает десять минут.","Какой прогноз сбылся? Что удивило?"],"9-12":["Задача: сохранить льдинку как можно дольше.","Ребёнок придумывает упаковку из домашних материалов.","Рядом кладёт льдинку без упаковки для сравнения.","Засекает время обеих и объясняет, что сработало."]}},{"id":"inventor-8","scale":"inventor","art":"☕💡🛠️","title":"Сделай удобнее","why":"Ребёнок учится замечать неудобство и предлагать решение. Так рождаются изобретения.","tip":"Спросите: «Что тебя в этой вещи раздражает?» С этого начинается любое улучшение.","need":{"3-5":"чашка или ложка, лист бумаги, мелки","6-8":"лист бумаги, карандаши","9-12":"картон, скотч, ножницы"},"steps":{"3-5":["Возьмите чашку. Спросите: что ей добавить, чтобы стала лучше?","Примите любую идею: крылья, колёса, вторую ручку.","Нарисуйте новую чашку вместе.","Придумайте ей название."],"6-8":["Ребёнок выбирает вещь, которой пользуется каждый день: рюкзак, пенал, кровать.","Называет, что в ней неудобно.","Придумывает три улучшения и рисует их.","Выбирает одно, которое можно сделать уже сегодня."],"9-12":["Ребёнок находит дома одно неудобство: провода путаются, обувь разбросана.","Придумывает решение и делает пробный образец из картона.","Семья пользуется им три дня.","Ребёнок собирает отзывы и дорабатывает."]}},{"id":"storyteller-6","scale":"storyteller","art":"📷👨‍👩‍👧💭","title":"История по фото","why":"Ребёнок достраивает то, чего нет в кадре: причину и продолжение. Это основа сюжета.","tip":"Спрашивайте «почему ты так думаешь?», чтобы ребёнок опирался на детали снимка.","need":{"3-5":"семейная фотография","6-8":"фото из журнала или книги","9-12":"три фотографии, лист бумаги"},"steps":{"3-5":["Откройте фото, где есть ребёнок или близкие.","Спросите: кто здесь? Что они делают?","А что было потом? Ребёнок придумывает.","Расскажите, как было на самом деле."],"6-8":["Выберите фото с незнакомыми людьми.","Ребёнок рассказывает, что было за минуту до снимка.","И что случится через минуту после.","Какая деталь на фото это подсказала?"],"9-12":["Ребёнок выбирает три никак не связанных фото.","Раскладывает их в ряд: начало, середина, конец.","Пишет к каждому по две фразы, чтобы получилась одна история.","Меняет порядок фото. Какой получится новая история?"]}},{"id":"storyteller-7","scale":"storyteller","art":"👽🪥💬","title":"Объясни инопланетянину","why":"Объяснить простое тому, кто ничего не знает, значит научиться говорить ясно.","tip":"Играйте всерьёз. Переспрашивайте: «А что такое вода?»","need":{"3-5":"мягкая игрушка","6-8":"зубная щётка или другой обычный предмет","9-12":"таймер"},"steps":{"3-5":["Игрушка прилетела с другой планеты и ничего не знает.","Ребёнок объясняет ей, что такое дождь.","Игрушка вашим голосом задаёт один вопрос.","Потом объясняет ей, как едят суп."],"6-8":["Вы инопланетянин. Ребёнок объясняет, зачем нужна зубная щётка.","Условие: слово «чистить» говорить нельзя.","Задайте два наивных вопроса.","Поменяйтесь: объясняете вы, а ребёнок переспрашивает."],"9-12":["Тема на выбор: интернет, деньги или школа.","Ребёнок объясняет её за одну минуту простыми словами.","Вы заранее запрещаете три самых очевидных слова.","Перескажите, что вы поняли. Совпало с тем, что хотелось сказать ребёнку?"]}},{"id":"storyteller-8","scale":"storyteller","art":"🐱🎩🎶","title":"Рифмы и строчки","why":"Рифма развивает слух к языку и учит подбирать точное слово.","tip":"Смешная и нелепая рифма тоже считается. Главное, чтобы было весело.","need":{"3-5":"ничего не нужно","6-8":"лист бумаги, карандаш","9-12":"лист бумаги, ручка"},"steps":{"3-5":["Назовите простое слово, например «кот».","Ищите вместе слова, которые звучат похоже.","Сложите из двух таких слов смешную строчку.","Повторите её хором три раза."],"6-8":["Тема: любимая игрушка или питомец.","Ребёнок подбирает две пары слов в рифму.","Складывает из них четыре строчки.","Читает стих семье с выражением."],"9-12":["Ребёнок выбирает любимую вещь или блюдо.","Пишет для неё рекламу в четыре строки с рифмой.","Придумывает короткий слоган.","Читает, как диктор. Вы говорите, купили бы или нет и почему."]}},{"id":"artist-6","scale":"artist","art":"🙂✏️🖼️","title":"Портрет","why":"Чтобы нарисовать лицо, нужно внимательно смотреть. Так рука учится доверять глазу.","tip":"Не оценивайте сходство. Спросите: «Что ты во мне замечаешь?»","need":{"3-5":"лист бумаги, мелки","6-8":"лист бумаги, фломастер","9-12":"два листа, карандаш"},"steps":{"3-5":["Сядьте напротив ребёнка.","Ребёнок рисует большой круг: это ваше лицо.","Называйте по очереди: глаза, нос, рот, волосы. Ребёнок добавляет.","Теперь вы рисуете ребёнка и слушаете подсказки."],"6-8":["Условие: рисуем портрет, не отрывая фломастер от бумаги.","Ребёнок рисует вас одной линией.","Вы так же рисуете ребёнка.","Найдите на портретах самую удачную деталь."],"9-12":["Первый портрет: ребёнок смотрит только на вас, на лист смотреть нельзя.","Две минуты, линия ведётся медленно.","Второй портрет обычный, тоже две минуты.","Сравните: на каком больше характера?"]}},{"id":"artist-7","scale":"artist","art":"🤸✨🗿","title":"Фигурка из фольги","why":"Объёмная фигура учит видеть форму со всех сторон и передавать движение.","tip":"Попросите показать позу своим телом. Потом её легче слепить.","need":{"3-5":"пластилин или солёное тесто","6-8":"фольга","9-12":"фольга или пластилин"},"steps":{"3-5":["Скатайте вместе три шарика и три колбаски.","Спросите: какого зверя из них можно собрать?","Ребёнок соединяет детали.","Зверь рассказывает вашим голосом, как его зовут."],"6-8":["Оторвите кусок фольги размером с лист бумаги.","Ребёнок сминает из него человечка: голова, руки, ноги.","Задача: человечек бежит, сидит или танцует.","Вы угадываете, что он делает."],"9-12":["Задача: фигура без лица, которая показывает чувство.","Ребёнок выбирает чувство и не говорит вам.","Лепит пять минут.","Вы угадываете. Что в позе подсказало ответ?"]}},{"id":"artist-8","scale":"artist","art":"🪟🌇✏️","title":"Вид из окна","why":"Ребёнок учится выбирать, что войдёт в кадр, и замечать, как свет меняет знакомое место.","tip":"Спросите: «Что здесь главное?» Это и есть композиция.","need":{"3-5":"окно, лист бумаги, мелки","6-8":"картонная рамка или сложенные пальцы, бумага, карандаши","9-12":"два листа, карандаш"},"steps":{"3-5":["Посмотрите вместе в окно одну минуту.","Ребёнок называет три вещи, которые видит.","Рисует их на листе.","Спросите, какая из трёх нравится больше всего."],"6-8":["Сделайте рамку из картона или из пальцев.","Ребёнок смотрит через неё в окно и выбирает кадр.","Рисует только то, что попало в рамку.","Даёт рисунку название."],"9-12":["Ребёнок делает набросок вида из окна утром, пять минут.","Вечером делает второй, с того же места.","Кладёт рядом.","Что изменил свет: цвета, тени, настроение?"]}},{"id":"explorer-6","scale":"explorer","art":"🍃🖍️🌳","title":"Отпечатки","why":"Ребёнок исследует поверхности руками и глазами и учится узнавать предмет по следу.","tip":"Угадывайте вслух и ошибайтесь. Пусть ребёнок вас поправит.","need":{"3-5":"бумага, восковой мелок, лист дерева, большая крышка","6-8":"бумага, мелок или мягкий карандаш","9-12":"бумага, мягкий карандаш, определитель или приложение"},"steps":{"3-5":["Положите лист дерева под бумагу.","Ребёнок трёт сверху мелком плашмя.","Смотрите вместе, как проявляется рисунок.","Повторите с крышкой. Чем отпечатки отличаются?"],"6-8":["На прогулке ребёнок делает пять отпечатков разных поверхностей.","Кора, плитка, скамейка, лист, стена дома.","Дома вы угадываете, где что.","Ребёнок подсказывает только «теплее» и «холоднее»."],"9-12":["Ребёнок делает отпечатки коры трёх разных деревьев.","Собирает по листу с каждого.","Определяет деревья по книге или приложению.","Подписывает отпечатки и собирает страницу каталога."]}},{"id":"explorer-7","scale":"explorer","art":"🌤️🌧️📝","title":"Бюро погоды","why":"Наблюдение за погодой учит замечать признаки и делать прогноз, который можно проверить.","tip":"Прогноз не сбылся? Спросите, какой признак подвёл.","need":{"3-5":"окно, игрушка, одежда для неё или лоскут","6-8":"листок, карандаш","9-12":"листок или тетрадь, градусник за окном или телефон"},"steps":{"3-5":["Посмотрите в окно: солнце, облака или дождь?","Качаются ли ветки? Значит, есть ветер.","Ребёнок решает, как сегодня одеть игрушку.","На прогулке проверьте, подошла ли одежда."],"6-8":["Вечером посмотрите вместе на небо.","Ребёнок записывает прогноз на завтра: солнце, облака или дождь.","Утром проверяет.","Три дня подряд. Сколько прогнозов сбылось?"],"9-12":["Неделю ребёнок записывает в одно и то же время: температуру, облака, ветер.","Каждый вечер пишет свой прогноз на завтра.","Сравнивает его с прогнозом в телефоне и с тем, что было.","В конце недели считает, кто был точнее."]}},{"id":"explorer-8","scale":"explorer","art":"👀🧩❔","title":"Что изменилось?","why":"Игра тренирует зрительную память и внимание к деталям.","tip":"Начинайте с простого. Трудность повышайте только после двух удач подряд.","need":{"3-5":"поднос, пять крупных предметов, полотенце","6-8":"комната","9-12":"картина или фото со множеством деталей, листок"},"steps":{"3-5":["Разложите на подносе пять предметов и назовите их вместе.","Накройте полотенцем и незаметно уберите один.","Что пропало?","Теперь убирает ребёнок, а угадываете вы."],"6-8":["Ребёнок минуту рассматривает комнату и выходит.","Вы меняете три вещи: переставляете, убираете, переворачиваете.","Ребёнок ищет изменения.","Поменяйтесь ролями."],"9-12":["Ребёнок одну минуту рассматривает картинку.","Уберите её и задайте десять вопросов о деталях.","Посчитайте верные ответы.","Теперь десять вопросов для вас готовит ребёнок."]}},{"id":"leader-6","scale":"leader","art":"👨‍👩‍👧🗳️✅","title":"Семейный совет","why":"Ребёнок учится выслушать каждого и довести обсуждение до решения.","tip":"Говорите только в свою очередь. Так ребёнок увидит, что правила совета действуют на всех.","need":{"3-5":"два варианта ужина или прогулки","6-8":"таймер на 5 минут","9-12":"лист бумаги, таймер"},"steps":{"3-5":["Назовите ребёнку два варианта.","Ребёнок спрашивает каждого в семье, что тот выбирает.","Считает голоса на пальцах.","Объявляет результат."],"6-8":["Вопрос совета: чем займёмся в выходные.","Ребёнок даёт слово каждому по очереди.","Повторяет все предложения вслух.","Проводит голосование и объявляет решение."],"9-12":["Ребёнок готовит три вопроса для обсуждения.","Ведёт совет: по три минуты на вопрос.","Записывает решения и кто за что отвечает.","Через неделю проверяет, что выполнено."]}},{"id":"leader-7","scale":"leader","art":"🧸📦🚀","title":"Командир миссии","why":"Ребёнок делит большое дело на части и раздаёт задачи. Это основа организации.","tip":"Выполняйте поручение точно как сказано. Неясное поручение сразу станет заметно.","need":{"3-5":"разбросанные игрушки, коробки","6-8":"комната, таймер на 10 минут","9-12":"лист бумаги, продукты для простого завтрака"},"steps":{"3-5":["Миссия: спасти игрушки и вернуть их домой.","Ребёнок командир: говорит, какую игрушку куда нести.","Вы выполняете и докладываете: «Мишка дома!»","Отпразднуйте конец миссии."],"6-8":["Миссия: порядок в комнате за 10 минут.","Ребёнок делит комнату на зоны и раздаёт их.","Следит за временем и помогает тому, кто отстаёт.","В конце благодарит команду."],"9-12":["Миссия: завтрак для семьи за 20 минут.","Ребёнок пишет список задач и порядок.","Раздаёт задачи. У плиты и с ножом работает взрослый.","После завтрака разбор: что стоило поручить иначе?"]}},{"id":"leader-8","scale":"leader","art":"⚖️🎲🤝","title":"Справедливый судья","why":"Ребёнок учится выслушать обе стороны и найти решение, которое примут все.","tip":"Примите решение судьи, даже если оно не в вашу пользу.","need":{"3-5":"простая игра по очереди: мяч или кубики","6-8":"настольная игра","9-12":"ничего не нужно"},"steps":{"3-5":["Ребёнок следит за очередью.","И говорит: «Теперь твой ход».","Нарушьте очередь один раз. Ребёнок должен это заметить.","Поблагодарите за честную игру."],"6-8":["Сегодня ребёнок судья.","Перед игрой судья объявляет правила.","Устройте небольшой спор. Судья решает, кто прав.","Спросите, почему решение именно такое."],"9-12":["Возьмите настоящий мелкий спор в семье.","Ребёнок выслушивает обе стороны, не перебивая.","Пересказывает каждую сторону так, чтобы она согласилась.","Предлагает решение, которое устроит обоих."]}},{"id":"helper-6","scale":"helper","art":"🪴💧🐹","title":"Забота о живом","why":"Регулярная забота о растении или питомце учит ответственности за того, кто от тебя зависит.","tip":"Не напоминайте сразу. Спросите: «Как там твой цветок?»","need":{"3-5":"комнатное растение, маленькая лейка, влажная тряпочка","6-8":"растение или питомец, листок-календарь","9-12":"растение или питомец, книга или сайт, листок"},"steps":{"3-5":["Выберите вместе цветок: теперь это цветок ребёнка.","Ребёнок поливает понемногу.","Протирает один лист тряпочкой.","Спросите: что цветку нравится?"],"6-8":["Ребёнок выбирает, о ком заботится неделю.","Вы вместе выясняете, что нужно подопечному и как часто.","Каждый день ребёнок отмечает сделанное в календаре.","В конце недели: что изменилось?"],"9-12":["Ребёнок выясняет, что нужно подопечному: свет, вода, корм.","Составляет памятку для семьи.","Отвечает за уход неделю.","Потом рассказывает, что было труднее всего."]}},{"id":"helper-7","scale":"helper","art":"👂💬❤️","title":"Я тебя слушаю","why":"Умение слушать, не перебивая, и пересказать услышанное лежит в основе дружбы.","tip":"Говорите коротко и о настоящем. Ребёнок чувствует, когда история выдумана.","need":{"3-5":"ничего не нужно","6-8":"таймер на 2 минуты","9-12":"ничего не нужно"},"steps":{"3-5":["Расскажите в трёх фразах, как прошёл ваш день.","Ребёнок повторяет: «Ты сегодня…»","Спросите: как думаешь, мне было весело или грустно?","Поменяйтесь: рассказывает ребёнок."],"6-8":["Вы две минуты рассказываете о своём дне.","Ребёнок слушает, не перебивая.","Задаёт один вопрос.","Пересказывает главное. Скажите, всё ли понято верно."],"9-12":["Ребёнок спрашивает кого-то из семьи, как прошёл день.","Задаёт три уточняющих вопроса.","Называет чувство: «Похоже, тебе было досадно».","Спрашивает, верно ли."]}},{"id":"helper-8","scale":"helper","art":"💛📝😊","title":"Добрые слова","why":"Ребёнок учится замечать хорошее в других и говорить об этом конкретно.","tip":"Покажите пример: скажите ребёнку, что именно сегодня получилось хорошо.","need":{"3-5":"семейный ужин","6-8":"листочки бумаги, карандаш","9-12":"листок или заметки в телефоне"},"steps":{"3-5":["За ужином ребёнок говорит каждому одно доброе слово.","Подскажите начало: «Мне нравится, как ты…»","Каждый отвечает «спасибо».","В конце доброе слово говорят ребёнку."],"6-8":["Ребёнок пишет каждому в семье записку.","В каждой одно конкретное дело: «Спасибо за починенный велосипед».","Прячет записки там, где их найдут.","Вечером обсудите, кто что нашёл."],"9-12":["В течение дня ребёнок замечает три хороших поступка других людей.","Записывает, кто что сделал.","Вечером говорит или пишет каждому об этом.","Обсудите: как люди отреагировали?"]}},{"id":"mover-6","scale":"mover","art":"🧘📚〰️","title":"Держи равновесие","why":"Равновесие связано с вниманием и осанкой и хорошо тренируется в игре.","tip":"Встаньте рядом на одну ногу. Вместе шататься веселее.","need":{"3-5":"верёвка или полоса скотча на полу, мягкая игрушка","6-8":"секундомер","9-12":"книга, секундомер, листок"},"steps":{"3-5":["Сделайте на полу линию.","Ребёнок идёт по ней, раскинув руки.","Теперь с игрушкой на голове.","Пройдите следом и уроните игрушку. Пусть посмеётся."],"6-8":["Ребёнок стоит на одной ноге. Засеките время.","Потом на другой. Какая устойчивее?","Теперь с закрытыми глазами, вы рядом.","Запишите три результата."],"9-12":["Ребёнок идёт по комнате с книгой на голове.","Усложнение: присесть и встать, не уронив.","Придумывает маршрут с поворотом.","Три попытки на время. Записывает рекорд."]}},{"id":"mover-7","scale":"mover","art":"🧦🧺🎯","title":"Меткий бросок","why":"Бросок в цель развивает глазомер и умение рассчитывать силу.","tip":"Бросаем только мягкое: свёрнутые носки или комочки бумаги.","need":{"3-5":"корзина или таз, пять пар свёрнутых носков","6-8":"корзина, носки, листок","9-12":"корзина, носки, листок"},"steps":{"3-5":["Поставьте корзину в двух шагах.","Ребёнок бросает пять носков.","Посчитайте попадания вслух.","Отойдите на шаг назад и повторите."],"6-8":["Отметьте три линии: близко, средне, далеко.","Попадание с каждой стоит 1, 2 и 3 очка.","У каждого по шесть бросков. Линию можно выбрать любую.","Посчитайте очки. Какая линия выгоднее?"],"9-12":["Ребёнок придумывает турнир: правила, очки, число раундов.","Один раунд бросаете слабой рукой.","Ребёнок ведёт таблицу.","После турнира меняет одно правило, чтобы стало интереснее."]}},{"id":"mover-8","scale":"mover","art":"🪞🙆🎵","title":"Зеркало","why":"Повторять движения за другим значит тренировать внимание, координацию и память на движения.","tip":"Двигайтесь медленно. Задача не запутать, а дать повторить.","need":{"3-5":"свободное место","6-8":"свободное место","9-12":"таймер, музыка"},"steps":{"3-5":["Встаньте напротив ребёнка.","Медленно поднимите руку. Ребёнок повторяет, как зеркало.","Добавьте наклон, шаг, приседание.","Теперь ведёт ребёнок, а зеркало вы."],"6-8":["Покажите связку из четырёх движений.","Ребёнок повторяет по памяти.","Затем добавляет пятое движение, вы повторяете всю связку.","Продолжайте, пока кто-то не собьётся."],"9-12":["Ребёнок составляет зарядку из шести упражнений на три минуты.","Подбирает к ней музыку.","Проводит зарядку для семьи.","Спрашивает, какое упражнение оставить, а какое заменить."]}}],"safety":"Задания выполняются вместе со взрослым. Ножницы, нож и горячее берёт взрослый."};
